		rep(j, 9) {
			if (j % 3 == j / 3) continue;
			rep(k, 9) {
				if (k % 3 == k / 3) continue;
				if (j % 3 == k % 3 || j / 3 == k / 3) continue;
				dp[i][k] = (dp[i][k] + dp[i-1][j]) % MOD;
			}
		}
	}

	vi pos;
