typedef long long LL;
int n;
char a[2][MaxN];
LL dp[MaxN][3][3];

int main() {
    scanf("%d%s%s",&n,a[0],a[1]);
    int i;
        memset(dp,0,sizeof dp);
    if (a[0][0]==a[1][0]) {
        dp[0][0][0]=dp[0][1][1]=dp[0][2][2]=1;
        i=1;
    } else {
        for (int i=0;i<3;++i) for (int j=0;j<3;++j)
            if (i!=j) dp[0][i][j]=dp[1][i][j]=1;
        i=2;
    }
    for (;i<n;++i) {
        if (a[0][i]==a[1][i]) {
            for (int j=0;j<3;++j) {
                //dp[i][j][j]=0;
                for (int x=0;x<3;++x) for (int y=0;y<3;++y) if (x!=j && y!=j) {
                    dp[i][j][j]+=dp[i-1][x][y];
                    dp[i][j][j]%=MOD;
                }
            }
        } else {
            for (int j=0;j<3;++j) for (int k=0;k<3;++k) if (j!=k) {
                //dp[i][j][k]=0;
                for (int x=0;x<3;++x) for (int y=0;y<3;++y) if (j!=x && k!=y) {
                    dp[i][j][k]+=dp[i-1][x][y];
                    dp[i][j][k]%=MOD;
                }
            }
            i++;
            for (int j=0;j<3;++j) for (int k=0;k<3;++k) dp[i][j][k]=dp[i-1][j][k];
        }
    }
    LL ans=0;
    for (int i=0;i<3;++i) for (int j=0;j<3;++j) ans=(ans+dp[n-1][i][j])%MOD;
    printf("%lld\n",ans);
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <algorithm>

const int kN = 100 + 5;
int n;
char s[2][kN];
const int MOD = (int)1e9 + 7;
int dp[kN][3][3];

bool ok(int a, int b, int x, int y)
{
    return a == b && x == y || a != b && x != y;
}

int work()
{
    for (int i = 0; i < 3; ++ i) {
        for (int j = 0; j < 3; ++ j) {
            if (!ok(i, j, s[0][0], s[1][0])) continue;
            dp[0][i][j] = 1;
        }
    }
    for (int at = 1; at < n; ++ at) {
        for (int i = 0; i < 3; ++ i) {
            for (int j = 0; j < 3; ++ j) {
                if (!ok(i, j, s[0][at], s[1][at])) continue;
                for (int k = 0; k < 3; ++ k) {
                    if (!ok(i, k, s[0][at], s[0][at - 1])) continue;
                    for (int r = 0; r < 3; ++ r) {
                        if (!ok(k, r, s[0][at - 1], s[1][at - 1]) ||
                            !ok(j, r, s[1][at], s[1][at - 1]))
                            continue;
                        dp[at][i][j] += dp[at - 1][k][r];
                        if (dp[at][i][j] >= MOD)
                            dp[at][i][j] -= MOD;
                    }
                }
            }
        }
    }
    int ret = 0;
    for (int i = 0; i < 3; ++ i)
        for (int j = 0; j < 3; ++ j) {
            ret += dp[n - 1][i][j];
            if (ret >= MOD)
                ret -= MOD;
        }
    return ret;
}

int main()
{
    scanf("%d", &n);
    scanf("%s%s", s + 0, s + 1);
    printf("%d\n", work());
}

