    for(int i=0;i<3;i++)for(int j=0;j<3;j++) if((str[0][1]==str[1][1]&&i==j) || (str[0][1]!=str[1][1]&&i!=j)) dp[0][i][j]=1;

    int cur=1,pr=0;
    for(int i=2;i<=n;i++) {
        for(int j=0;j<3;j++)for(int k=0;k<3;k++) {
            dp[cur][j][k]=0;
            if((str[0][i]==str[1][i] && j!=k) || (str[0][i]!=str[1][i] && j==k)) continue;

            for(int a=0;a<3;a++)for(int b=0;b<3;b++) {
