int dp[55][16];

int main() {
	ios_base::sync_with_stdio(false); cin.tie(0);
	cin >> n;
	a[1][0] = a[2][0] = '*';
	for (int i = 1; i <= 2; ++i) {
		for (int j = 1; j <= n; ++j) cin >> a[i][j];
	}

	dp[0][0] = 1;
	for (int i = 1; i <= n; ++i) {
		for (int mask = 0; mask < (1 << 4); ++mask) if (dp[i - 1][mask]) {
			int c1 = mask >> 2, c2 = mask & 3;
			for (int nc1 = 1; nc1 <= 3; ++nc1) for (int nc2 = 1; nc2 <= 3; ++nc2) {
				if (a[1][i - 1] == a[1][i] && c1 != nc1) continue;
				else if (a[1][i - 1] != a[1][i] && c1 == nc1) continue;

				if (a[2][i - 1] == a[2][i] && c2 != nc2) continue;
				else if (a[2][i - 1] != a[2][i] && c2 == nc2) continue;

				if (a[1][i] == a[2][i] && nc1 != nc2) continue;
				else if (a[1][i] != a[2][i] && nc1 == nc2) continue;

				dp[i][nc1 * 4 + nc2] += dp[i - 1][mask];
				while (dp[i][nc1 * 4 + nc2] >= mod) dp[i][nc1 * 4 + nc2] -= mod;
			}
		}
	}

	int ans = 0;
	for (int mask = 0; mask < 16; ++mask) ans = (ans + dp[n][mask]) % mod;
