#include <stdio.h>
#include <stdlib.h>

#define MAX_N (52)
#define SIZE_BUF (30)
#define NUM_MOD (1000000007)

long solve(const char *S, int N, int j) {
  if (j >= N) {
    return 1;
  }
  const int cur_pattern = S[j + 0 * N] == S[j + 1 * N];
  if (j > 0) {
    const int prev_pattern = S[j - 1 + 0 * N] == S[j - 1 + 1 * N];
    if (prev_pattern && cur_pattern) {
      return (2 * solve(S, N, j + 1)) % NUM_MOD;
    } else if (prev_pattern && !cur_pattern) {
      return (2 * solve(S, N, j + 2)) % NUM_MOD;
    } else if (!prev_pattern && cur_pattern) {
      return (1 * solve(S, N, j + 1)) % NUM_MOD;
    } else {
      return (3 * solve(S, N, j + 2)) % NUM_MOD;
    }
  } else {
    if (cur_pattern) {
      return (3 * solve(S, N, j + 1)) % NUM_MOD;
    } else {
      return (6 * solve(S, N, j + 2)) % NUM_MOD;
    }
  }
}

int main(int argc, char *argv[]) {
  // read inputs
  int N;
  char S[2 * MAX_N + 1], buf[SIZE_BUF];
  scanf("%d", &N);
  fgets(buf, SIZE_BUF, stdin);
  for (int i = 0; i < 2; i++) {
    scanf("%s", &S[i * N]);
    fgets(buf, SIZE_BUF, stdin);
  }

  // solve
  printf("%ld\n", solve(S, N, 0));

  return 0;
}

