    cin >> n;
    cin >> (mat[1] + 1) >> (mat[2] + 1);

    int st;
    if (mat[1][1] == mat[2][1]) {
        dp[1][0][0] = dp[1][1][1] = dp[1][2][2] = 1;
        st = 2;
    }
    else {
        dp[2][0][1] = dp[2][0][2] = dp[2][1][0] = dp[2][1][2] = dp[2][2][0] = dp[2][2][1] = 1;
        st = 3;
    }

    for (int i = st; i <= n; ++i) {
        if (mat[1][i] == mat[1][i + 1])
            continue;

        if (mat[1][i] == mat[2][i]) {
            for (int k = 0; k <= 2; ++k) {
                for (int p1 = 0; p1 <= 2; ++p1)
                for (int p2 = 0; p2 <= 2; ++p2)
                    if (k != p1 && k != p2)
                        dp[i][k][k] = (dp[i][k][k] + dp[i - 1][p1][p2]) % MOD;
            }
        } else {
            for (int p1 = 0; p1 <= 2; ++p1)
            for (int p2 = 0; p2 <= 2; ++p2)
            for (int q1 = 0; q1 <= 2; ++q1)
            for (int q2 = 0; q2 <= 2; ++q2)
                if (p1 != p2 && p1 != q1 && p2 != q2)
                    dp[i][p1][p2] = (dp[i][p1][p2] + dp[i - 2][q1][q2]) % MOD;
        }
    }

    int ans = 0;
    for (int p1 = 0; p1 <= 2; ++p1)
