                        }
                    }
                }
                dp[i][j][j] %= md;
            }
        }else if(S[0][i] == S[0][i - 1]){
            for(ll k = 0; k < 3; ++k){
                for(ll l = 0; l < 3; ++l){
                    dp[i][k][l] = dp[i - 1][k][l];
                }
            }
        }else{
            for(ll j = 0; j < 3; ++j){
                for(ll m = 0; m < 3; ++m){
                    if(j != m){
                        for(ll k = 0; k < 3; ++k){
                            for(ll l = 0; l < 3; ++l){
                                if(j != k && m != l){
