int solve()
{
	int m = 0;
	for (int i = 1; i <= n; ++i)
	{
		++m;
		if (s[0][i] == s[1][i])
		{
			t[0][m] = t[1][m] = s[0][i];
		}
		else
		{
			if (s[0][i] != s[0][i + 1])return 0;
			if (s[1][i] != s[1][i + 1])return 0;
			t[0][m] = s[0][i];
			t[1][m] = s[1][i];
			++i;
		}
	}
	n = m;
	memcpy(s, t, sizeof(t));

	MS(f, 0);
	f[0][3][3] = 1;
	for (int i = 1; i <= n; ++i)
	{
		for (int j = 0; j <= 3; ++j)
		{
			for (int k = 0; k <= 3; ++k)
			{
				if (s[0][i] == s[1][i])
				{
					for (int u = 0; u < 3; ++u)if (u != j && u != k)
					{
						gadd(f[i][u][u], f[i - 1][j][k]);
					}
				}
				else
				{
					for (int u = 0; u < 3; ++u)if (u != j)
					{
						for (int v = 0; v < 3; ++v)if (v != k && v != u)
						{
							gadd(f[i][u][v], f[i - 1][j][k]);
						}
					}
				}
			}
		}
	}
	int ans = 0;
	for (int j = 0; j < 3; ++j)
	{
		for (int k = 0; k < 3; ++k)
		{
			gadd(ans, f[n][j][k]);
		}
	}
	return ans;
}
