  for (int j = 0; j < 3 * 3; j++) {
    int u = j / 3, d = j % 3;
    if (S[0][0] == S[1][0]) {
      dp[0][j] = u == d;
    } else {
      dp[0][j] = u != d;
    }
  }
  for (int i = 1; i < N; i++) {
    for (int j = 0; j < 3 * 3; j++) {
      for (int k = 0; k < 3 * 3; k++) {
        int u = j / 3, d = j % 3;
        int uu = k / 3, dd = k % 3;
        if (S[0][i] == S[1][i]) {
          dp[i][k] += dp[i-1][j] * (uu == dd) * (u != uu) * (d != dd);
        } else if (S[0][i-1] == S[0][i]) {
          dp[i][k] += dp[i-1][j] * (u == uu) * (d == dd);
        } else {
          dp[i][k] += dp[i-1][j] * (u != uu) * (d != dd) * (uu != dd);
        }
        dp[i][k] %= MOD;
      }
    }
  }
  ll res = 0;
  for (int j = 0; j < 3 * 3; j++) {
    res = (res + dp[N-1][j]) % MOD;
  }
