typedef std::pair<int, int> ii;
typedef std::pair<ii, char> ic;
typedef long long ll;

const ii INF = ii(1e9, 1e9);
const ll MOD = 1e9 + 7;
std::vector<ii> pt[256];
std::vector<ii> piece;
int dec[256];
int step[256], cur_step = 0, step2[256][2];

int n;
std::string dom[2];

std::vector<int> to[256];
ll memo[256][3][3];

ll dp(int on, int f1, int f0)
{
	if(on == piece.size())
		return 1;
	ll &ans = memo[on][f1][f0];
	if(ans != -1)
		return ans;
	ans = 0;
	bool b1 = false, b0 = false;
	for(int i = 0; i < to[on].size(); i++)
	{
		if(to[on][i] == 1)
			b1 = true;
		else if(to[on][i] == 0)
			b0 = true;
	}
	for(int i = 0; i < 3; i++)
	{
		if(b1 && f1 == i)
			continue;
		if(b0 && f0 == i)
			continue;
		ans += dp(on + 1, f0, i);
	}
	ans %= MOD;
	return ans;
}

int dx[] = {0, 1, 0, -1};
int dy[] = {1, 0, -1, 0};

void dfs(ii pos, char x)
{
	if(step2[pos.first][pos.second] == cur_step)
		return;
	step2[pos.first][pos.second] = cur_step;
	step[dec[dom[pos.second][pos.first]]] = cur_step;
	//std::cout << "on (" << pos.second << ", " << pos.first << ")\n";
	if(dom[pos.second][pos.first] != x)
		return;
	for(int i = 0; i < 4; i++)
	{
		ii to = ii(pos.first + dx[i], pos.second + dy[i]);
		if(to.first < 0 || to.first >= dom[0].size())
			continue;
		if(to.second < 0 || to.second >= 2)
			continue;
		dfs(to, x);
	}
}

