{
	std::cin >> n >> dom[0] >> dom[1];
	for(int i = 0; i < n; i++)
	{
		for(int j = 0; j < 2; j++)
		{
			pt[dom[j][i]].push_back(ii(i, j));
		}
	}
	for(int i = 0; i < 256; i++)
	{
		std::sort(pt[i].begin(), pt[i].end());
		if(pt[i].size() != 0)
			piece.push_back(pt[i][0]);
	}
	std::sort(piece.begin(), piece.end());
	for(int i = 0; i < piece.size(); i++)
		dec[dom[piece[i].second][piece[i].first]] = i;
	for(int i = 0; i < piece.size(); i++)
	{
		cur_step++;
		//std::cout << i << ": (" << piece[i].second << ", " << piece[i].first << "), " << dom[piece[i].second][piece[i].first] << "\n";
		dfs(piece[i], dom[piece[i].second][piece[i].first]);
		for(int j = 0; j < i; j++)
		{
			if(step[j] == cur_step)
			{
				to[i].push_back(i - j - 1);
				//std::cout << "got (" << i << ", " << j << ")\n";
			}
		}
	}
	memset(memo, -1, sizeof memo);
	std::cout << dp(0, 0, 0) << '\n';
}

