// Returns Run Length Enconding of an input vector.
// Verified: AGC040A
template<typename T> vector<pair<T, int>> RLE(vector<T> xs) {
  vector<pair<T, int>> es;

  T current = xs[0];
  int current_count = 1;
  for (int i = 1; i < xs.size(); i++) {
    if (xs[i] == current) {
      current_count++;
    } else {
      es.push_back(make_pair(current, current_count));
      current = xs[i];
      current_count = 1;
    }
  }
  es.push_back(make_pair(current, current_count));
  return es;
}

