LL F(LL pos,LL up,LL down)
{
	if( pos > N )return 1;

	if( dp[pos][up][down] != -1 )return dp[pos][up][down];

	LL ret = 0;
	if( ara[pos] == 1 )
	{
		if( up == 0 )
		{
			LL i;
			rep(i,3)ret = ret + F(pos+1,i,i);
		}
		else
		{
			LL i;
			rep(i,3)
			{
				if( up != i && down != i )ret = ret + F(pos+1,i,i);
			}
		}
	}
	else
	{
		if( up == 0 )
		{
			LL i,j;
			rep(i,3)
			{
				rep(j,3)
				{
					if( i == j )continue;
					ret = ret + F(pos+1,i,j);
				}
			}
		}
		else
		{
			LL i,j;
			rep(i,3)
			{
				if( up == i ) continue;
				rep(j,3)
				{
					if( down == j )continue;
					if(i == j)continue;
					ret = ret + F(pos+1,i,j);
				}
			}
		}
	}

	return dp[pos][up][down] = ret % mod;
}

