int N;
char s1[60],s2[60];
LL dp[60];
void solve()
{
    for(int i=1;i<=N;i++)
    {
        if(i==1)
        {
            if(s1[i]==s2[i])
            {
                dp[1] = 3;
            }
            else
            {
                dp[1] = dp[2] = 6;
                i++;
            }
        }
        else
        {
            if(s1[i]==s2[i])
            {
                if(s1[i-1]==s2[i-1])
                {
                    dp[i] = 2LL*dp[i-1];
                    if(dp[i]>mod) dp[i]%=mod;
                }
                else
                {
                    dp[i] = 2LL*dp[i-1];
                    if(dp[i]>mod) dp[i]%=mod;
                }
            }
            else
            {
                if(s1[i-1]==s2[i-1])
                {
                    dp[i] = dp[i+1] = dp[i-1];
                }
                else
                {
                    dp[i] = dp[i+1] = dp[i-1]*3LL;
                    if(dp[i]>mod) dp[i]%=mod,dp[i+1]%=mod;
                }
                i++;
            }
        }

        // debug(i)
        // debug(dp[i])
    }
    LL ans = dp[N]%mod;
    out(ans);puts("");
}
int main()
{
    //std::ios::sync_with_stdio(false);
