        if( s[0][i] == s[0][i+1] ){ //横が同じ
            if(flag == true){ // 前回が立て向き
                p = (p*2) % mod;
            }else if(flag == false){ //前回が横向き
                p = (p*3) % mod; 
            }
            flag = false;
            i += 2;
        }else if( s[0][i] == s[1][i] ){ //立てが同じ
            if(flag == true){ // 前回が立て向き
                p = (p*2) % mod;
            }else if( flag == false){ //前回が横向き
                p = (p*1) % mod;
            }
            i++;
            flag = true;
        }
    }

    cout << p << endl;

    return 0;
}

