int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int n;
	cin >> n;
	string s1, s2;
	cin >> s1 >> s2;
	string str[2];
	str[0] = s1;
	str[1] = s2;

	// 左から塗っていく
	// 縦棒の一本の場合と、横棒2本の場合のみ
	bool prevHori;
	vector<ll> num(n, 0);
	if (str[0][0] == str[1][0]) {
		num[0] = 3;
		prevHori = false;
	}
	else {
		num[0] = 6;
		num[1] = 6;
		prevHori = true;
	}
	Rep(j, 1, n) {
		if (num[j] != 0) continue;
		if (str[0][j] == str[1][j]) {
			if (prevHori) num[j] = 1;
			else num[j] = 2;
			prevHori = false;
		}
		else {
			if (prevHori) {
				num[j] = 3;
				num[j + 1] = 3;
			}
			else {
				num[j] = 2;
				num[j + 1] = 2;
			}
			prevHori = true;
		}
	}

	ll ans = 1;

	rep(j, n) {
		ans *= num[j];
		ans %= mod;
		if (str[0][j] != str[1][j])
			j++;
	}

	cout << ans << endl;

	return 0;
}

