ll N;
string S1, S2;
vector<int> pattern;
int main()
{
    cin >> N >> S1 >> S2;
    REP(i, S1.length()) {
        if(S1[i] == S2[i]) {
            pattern.push_back(1);
        } else {
            pattern.push_back(2);
            i++;
        }
    }
    ll ans = 0;
    if(pattern[0] == 1) { ans = 3; }
    else { ans = 6; }
    for(int i = 1; i < pattern.size(); ++i) {
        if(pattern[i-1] == 1 && pattern[i] == 1) {
            ans *= 2;
        }
        else if(pattern[i-1] == 1 && pattern[i] == 2) {
            ans *= 2;
        }
        else if(pattern[i-1] == 2 && pattern[i] == 1) {
            ans *= 1;
        }
        else if(pattern[i-1] == 2 && pattern[i] == 2) {
            ans *= 3;
        }
        ans %= MOD;
    }
    printf("%lld\n", ans);

    return 0;
}

