const int inf = 1000000007;
long long ans;
int same(int prev)
{
    if(prev == 1){
        ans = ans * 2;
    }
    if(prev == 0){
        ans = ans * 3;
    }
    s1.erase(s1.size() - 1, 1);
    s2.erase(s2.size() - 1, 1);
    ans = ans % inf;
    return 1;
}

int dif(int prev)
{
    if(prev == 2){
        ans = ans * 3;
    }
    if(prev == 1){
        ans = ans * 2;
    }
    if(prev == 0){
        ans = ans * 6;
    }
    s1.erase(s1.size() - 1, 1);
    s1.erase(s1.size() - 1, 1);
    s2.erase(s2.size() - 1, 1);
    s2.erase(s2.size() - 1, 1);
    ans = ans % inf;
    return 2;
}


