int type(int i, string &s1, string &s2) {
  if (s1[i] == s2[i]) {
    return 1;
  }
  return 2;
}

void solve() {
  const int mod = 1000000007;
  int N;
  cin >> N;
  string s1, s2;
  cin >> s1 >> s2;
  int t = type(0, s1, s2);
  ll ans = 0;
  if (t == 1) {
    ans = 3;
  } else {
    ans = 6;
  }
  int prett = t;
  while(t < N) {
    int tt = type(t, s1, s2);
    if (prett == 1 && tt == 1) {
      ans *= 2;
      ans %= mod;
    }
    if (prett == 1 && tt == 2) {
      ans *= 2;
      ans %= mod;
    }
    if (prett == 2 && tt == 2) {
      ans *= 3;
      ans %= mod;
    }
    prett = tt;
    t += tt;
  }
  cout << ans << endl;
}

