long long CalcComb() {

	long long ans;

	int bef;//1つ前のドミノが立て向きなら0横なら1

	for (int i = 0; i < N;i++) {

		if (S1[i] == S1[i + 1]) {//横向き
			bef = 1;
			if (i == 0) ans = 6;
			else if (bef == 1) ans = (ans * 3) % MOD;//前も自分も横向き
			else if (bef == 0) ans = (ans * 2) % MOD;
			i++;
		}
		else if (S1[i] != S1[i + 1]) {//縦向き
			bef = 0;
			if (i == 0) ans = 3;
			else if (bef == 1) continue;
			else if (bef == 0) ans = (ans * 2) % MOD;
		}


	}

	return ans;
}

