void solve() {
    cin >> n;
    FOR(i, 0, 2) cin >> s[i];
    int ans = 1;
    FOR(i, 0, n) {
        if (s[0][i] == s[1][i]) {
            if (!i) {
                ans = mult(ans, 3);
            }
            else {
                if (s[0][i - 1] == s[1][i - 1]) {
                    ans = mult(ans, 2);
                }
            }
        }
        else {
            if (!i) {
                ans = mult(ans, 6);
            }
            else {
                if (s[0][i - 1] == s[1][i - 1]) {
                    ans = mult(ans, 2);
                }
                else {
                    ans = mult(ans, 3);
                }
            }
            i++;
        }
    }
    cout << ans << "\n";
}

