void solve(void)
{
  int N; cin >> N;
  string S1, S2; cin >> S1 >> S2;
  if (N == 1) {
    if (S1[0] == S2[0]) {
      cout << 3 << CRLF;
      return;
    } else {
      abort();
    }
  }

  ll res = 3;
  int itr = 1;
  if (S1[0] == S1[1]) {
    res *= 2;
    ++itr;
  }
  bool tyokuzenGaTate = S1[0] == S2[0];
  while (itr < N) {
    if (itr == N-1) {
      if (tyokuzenGaTate) {
        res *= 2;
        res %= MOD;
      } else {
        res *= 1;
        res %= MOD;
      }
      ++itr;
      continue;
    }

    bool isTate = S1[itr] == S2[itr];
    if (isTate) {
      if (tyokuzenGaTate) {
        res *= 2;
        res %= MOD;
      } else {
        res *= 1;
        res %= MOD;
      }
      tyokuzenGaTate = true;
      ++itr;
    } else {
      if (tyokuzenGaTate) {
        res *= 2;
        res %= MOD;
      } else {
        res *= 3;
        res %= MOD;
      }
      tyokuzenGaTate = false;
      itr += 2;
    }
  }
  cout << res << CRLF;
  return;
}

