            {
                ret += solve(i+1,j+1,1,1);
                ret %= mod;
                ret += solve(i+1,j+1,2,2);
                ret %= mod;
                ret += solve(i+1,j+1,3,3);
                ret %= mod;
            }
            else
            {
                ret += solve(i+2,j,1,d);
                ret %= mod;
                ret += solve(i+2,j,2,d);
                ret %= mod;
                ret += solve(i+2,j,3,d);
                ret %= mod;
            }
        }
        else
        {
            if(s[0][i] == s[1][j])
            {
                if(u != 1 && d != 1)
                {
                    ret += solve(i+1,j+1,1,1);
                    ret %= mod;
                }
                if(u != 2 && d != 2)
                {
                    ret += solve(i+1,j+1,2,2);
                    ret %= mod;
                }
                if(u != 3 && d != 3)
                {
                    ret += solve(i+1,j+1,3,3);
                    ret %= mod;
                }
            }
            else
            {
                if(u != 1)
                {
                    ret += solve(i+2,j,1,d);
                    ret %= mod;
                }
                if(u != 2)
                {
                    ret += solve(i+2,j,2,d);
                    ret %= mod;
                }
                if(u != 3)
                {
                    ret += solve(i+2,j,3,d);
                    ret %= mod;
                }
            }
        }
    }
    else
    {
        if(u != 1 && d != 1)
        {
            ret += solve(i,j+2,u,1);
            ret %= mod;
        }
        if(u != 2 && d != 2)
        {
            ret += solve(i,j+2,u,2);
            ret %= mod;
        }
        if(u != 3 && d != 3)
        {
            ret += solve(i,j+2,u,3);
            ret %= mod;
        }
    }
    return ret;
}

