void dfs(int x,int flag,ll ans)
{
    if(x==n)
    {
        sum=(sum+ans)%Mod;
        return ;
    }
    if(x+1<n&&s1[x]==s1[x+1]&&s2[x]==s2[x+1])
    {
        if(!flag)
            dfs(x+2,2,ans*6%Mod);
        else if(flag==1)
            dfs(x+2,2,ans*2%Mod);
        else
            dfs(x+2,2,ans*3%Mod);
    }
    if(s1[x]==s2[x])
    {
        if(!flag)
            dfs(x+1,1,ans*3%Mod);
        else if(flag==1)
            dfs(x+1,1,ans*2%Mod);
        else
            dfs(x+1,1,ans*1%Mod);
    }
}
