int main(void) {
    int N;
    string S, T;
    cin >> N >> S >> T;

    int64_t ans;
    if(S[0] == T[0]) {
        ans = 3;
    } else {
        ans = 6;
    }

    for(int i=1; i<N; i++) {
        if(S[i] == T[i]) {
            if(S[i-1] == T[i-1]) {
                ans *= 2;
            }
        } else if(S[i-1] == T[i-1]) {
            ans *= 2;
        } else if(S[i-1] != S[i]) {
            ans *= 3;
        }
        ans %= MOD;
    }

    cout << ans << endl;
    return 0;
}

