const int N = 1000007;
#define int long long
#define mod inf

int n, block[N], ind = 0, dp[N][3], dp1[N][3][3];
string row1, row2;


void solveDP()
{
  if (block[1] == 0)
  {
    rep(c1, 3) rep(c2, 3)
    {
      if (c1 == c2) continue;
      dp1[1][c1][c2] = 1;
    }
  }
  else
  {
    rep(c0, 3)
    {
      dp[1][c0] = 1;
    }
  }

  for (int i=2; i<=ind; ++i)
  {
    if (block[i] == 1 && block[i-1] == 1)
    {
      rep(c0, 3) rep(c1, 3)
      {
        //if (c0 == c1) continue;
        if (c0 == c1) continue;
        dp[i][c0] += dp[i-1][c1];
        dp[i][c0] %= mod;
      }
    }
    else if (block[i] == 1 && block[i-1] == 0)
    {
      rep(c0, 3) rep(c1, 3) rep(c2, 3)
      {
        //if (c0 == c1 || c0 == c2 || c1 == c2) continue;
        if (c0 == c1 || c0 == c2 || c1 == c2) continue;
        dp[i][c0] += dp1[i-1][c1][c2];
        dp[i][c0] %= mod;
      }
    }
    else if (block[i] == 0 && block[i-1] == 1)
    {
      rep(c1, 3) rep(c2, 3) rep(c3, 3)
      {
        //if (c1 == c2 || c1 == c3 || c2 == c3) continue;
        if (c3 == c1 || c3 == c2 || c1 == c2) continue;
        dp1[i][c1][c2] += dp[i-1][c3];
        dp1[i][c1][c2] %= mod;
      }
    }
    else if (block[i] == 0 && block[i-1] == 0)
    {
      rep(c1, 3) rep(c2, 3) rep(c3, 3) rep(c4, 3)
      {
        //if (c1 == c2 || c1 == c3 || c1 == c4 || c2 == c3 || c2 == c4 || c3 == c4) continue;
        if (c1 == c2 || c3 == c4 || c1 == c3 || c2 == c4) continue;
        dp1[i][c1][c2] += dp1[i-1][c3][c4];
        dp1[i][c1][c2] %= mod;
      }
    }
  }

  int rst = 0;
  if (block[ind] == 1)
  {
    rep(c0, 3) rst += dp[ind][c0], rst %= mod;
  }
  else
  {
    rep(c1, 3) rep(c2, 3)
    {
      if (c1 == c2) continue;
      rst += dp1[ind][c1][c2], rst %= mod;
    }
  }

  cout<<rst;
}


void solve()
{
  cin>>n>>row1>>row2;
  row1 = '#' + row1 + '#';
  row2 = '#' + row2 + '#';

  for (int i=1; i<=n;)
  {
    if (row1[i] == row1[i+1]) block[++ind] = 0, i+=2; //dwa poziome
    else if (row1[i] == row2[i]) block[++ind] = 1, ++i; //pion
  }
  pa(block, ind);
  pv(ind);

  solveDP();

  for (int i=1; i<=ind; ++i)
  {
    pv(i);
    if (block[i] == 1)
    {
      rep(c0, 3)
      {
        pv(c0, dp[i][c0]);
      }
    }
    else
    {
      rep(c1, 3) rep(c2, 3)
      {
        pv(c1, c2, dp1[i][c1][c2]);
      }
    }

    endr;
  }
}

int32_t main()
{
ios_base::sync_with_stdio(0); cin.tie(NULL);
cout<<fixed<<setprecision(10);

  solve();

return 0;
}

