int main() {
	int N; string S[2];

	cin >> N >> S[0] >> S[1];

	int ans = 1;

	int x = 0;
	int pre = -1;

	while (x < N) {

		//縦
		if (S[0][x] == S[1][x]) {

			//初回は自由に3つ選べる。
			if (pre < 0)ans = 3;

			//前回が縦なら、使っていない2色選べる。
			else if (pre == 0)ans * 2;

			//前回が横なら、残り1色しかおけない。
			else ans *= 1;

			//幅を1個進める。
			//履歴を縦を選んだことにする。
			x++; pre = 0;
		}

		//横
		else {

			//初回、6 3色選んで、残った2色を選ぶ
			if (pre < 0)ans = 6;
			//前回が縦なら、使ってない2色、残りの1色で2*1=2
			else if (pre == 0)ans *= 2;

			//前回が横ならBA BC CAの3種類
			//A| BB C
			//B| AC A

			else ans *= 3;

			//幅を2個進める。
			//履歴を横に選んだことにする。
			x += 2; pre = 1;
		}
	}

	cout << ans << endl;

	return 0;
}

