using namespace std;
typedef long long lint;

const int MAXN = 60;
const int MOD = 1e9+7;
lint dp[MAXN][4][4];

int main() {
  int N;
  cin >> N;
  vector<string> S(2);
  for (int i = 0; i < 2; i++) {
    cin >> S[i];
  }
  dp[0][0][0] = 1;
  for (int i = 0; i < N; ) {
    if (S[0][i] == S[1][i]) {
      // 同じドミノ
      for (int c = 1; c < 4; c++) {
        for (int c1 = 0; c1 < 4; c1++) {
          for (int c2 = 0; c2 < 4; c2++) {
            if (c != c1 && c != c2) {
              dp[i+1][c][c] += dp[i][c1][c2];
              dp[i+1][c][c] %= MOD;
            }
          }
        }
      }
      i++;
    } else {
      // 異なるドミノ
      // dp[i+1] = dp[i] として i は 2 つ進める
      for (int c1 = 1; c1 < 4; c1++) {
        for (int c2 = 1; c2 < 4; c2++) {
          if (c1 == c2) continue;
          for (int c3 = 0; c3 < 4; c3++) {
            for (int c4 = 0; c4 < 4; c4++) {
              if (c1 == c3 || c2 == c4) continue;
              dp[i+1][c1][c2] += dp[i][c3][c4];
              dp[i+1][c1][c2] %= MOD;
            }
          }
        }
      }
      for (int c1 = 0; c1 < 4; c1++) {
        for (int c2 = 0; c2 < 4; c2++) {
          dp[i+2][c1][c2] = dp[i+1][c1][c2];
        }
      }
      i += 2;
    }
  }
  lint ans = 0;
  for (int i = 0; i < 4; i++) {
    for (int j = 0; j < 4; j++) {
      ans += dp[N][i][j];
    }
  }
  cout << ans%MOD << endl;
  return 0;
}

