int dp(int n,int pd,int ppd,int pc,int ppc){
    if(mem[n][pd][ppd][pc][ppc]!=-1)return mem[n][pd][ppd][pc][ppc];
    if(n==N){
        return 1;
    }
    int res=0;
    int now = domino[n].second.second;
    int x = domino[n].first,y=domino[n].second.first;
    if(n==0)res=dp(n+1,now,pd,0,pc)+dp(n+1,now,pd,1,pc)+dp(n+1,now,pd,2,pc);
    else if(n==1)res=dp(n+1,now,pd,(pc+1)%3,pc)+dp(n+1,now,pd,(pc+2)%3,pc);
    else if(now == 0){
        if(pd==0&&ppd==0){
            if(y==0)res=dp(n+1,now,pd,(pc+1)%3,pc)+dp(n+1,now,pd,(pc+2)%3,pc);
            else res=dp(n+1,now,pd,3-(pc+ppc),pc);
        }
        else if(pd==0&&ppd==1){
            res=dp(n+1,now,pd,3-(pc+ppc),pc);
        }
        else if(pd==1){
            res=dp(n+1,now,pd,(pc+1)%3,pc)+dp(n+1,now,pd,(pc+2)%3,pc);
        }
    }
    else {
        if(pd==0&&ppd==0){
            res=dp(n+1,now,pd,3-(pc+ppc),pc);
        }
        else if(pd==1){
            res=dp(n+1,now,pd,(pc+1)%3,pc)+dp(n+1,now,pd,(pc+2)%3,pc);
        }
    }
    return mem[n][pd][ppd][pc][ppc]=res%mod;
}


