	cin >> n;
	string s[2];
	cin >> s[0] >> s[1];

	for(int j = 0; j < n; ++j){
		for(int i = 0; i < 2; ++i){
			//no es el caso base
			if(i == 0 && j == 0) dp[i][j] = 3;
			//no es la sugunda parte de un palo vertical
			else if(i == 1 && s[0][j] == s[1][j]) dp[1][j] = dp[0][j];
			//no es la segunda parte de un palo horizontal
			else if(j and s[i][j] == s[i][j-1]) dp[i][j] = dp[i][j-1];
			else {
				//es la primera parte de uno vertical
				if(i == 0 && s[1][j] == s[0][j]) {
					if(j) {
						if(s[0][j-1] == s[1][j-1]) {
							dp[i][j] = dp[i][j-1] * 2;
						}
						else {
							dp[i][j] = dp[1][j-1];
						}
					}
				}

				else if(i == 0) {
					dp[i][j] = dp[i][j-1] * 2;
				}

				else if(i == 1) {
					if(j) {
						if(s[0][j-1] == s[1][j-1]) 	dp[i][j] = dp[i-1][j];
						else {
							dp[i][j] = (3*dp[i][j-1]);
						}
					}
					else dp[i][j] = dp[i-1][j] * 2;
				}
			}
			mod(dp[i][j]);
		}
	}

	cout << dp[1][n-1] << endl;
}

