int64_t go(int ix,int x,int y) {
    assert(x < 3 && y < 3);
    if(ix >= n) return 1;
    if(dp[ix][x][y]) return dp[ix][x][y];
    int64_t ans = 0;
    if(a[0][ix] == a[1][ix]) {
        if(x != y) {
            ans = go(ix+1,3-x-y,3-x-y);
        } else {
            for(int i=0;i<3;i++) if(i != x) {
                ans += go(ix+1,i,i); ans %= MOD;
            }
        }
    } else {
        if(x != y) {
            ans += go(ix+2,y,3-x-y); ans %= MOD;
            ans += go(ix+2,3-x-y,x); ans %= MOD;
            ans += go(ix+2,y,x); ans %= MOD;
        } else {
            for(int i=0;i<3;i++) if(i == x) {
                int _x = (i+1)%3, _y = (i+2)%3;
                ans += go(ix+2,_x,_y); ans %= MOD;
                ans += go(ix+2,_y,_x); ans %= MOD;
            }
        }
    }
    dp[ix][x][y] = ans;
    return ans;
}

