int N;

lint recursion(int ind, int col) {
	if (ind == N) {
		return 1;
	}
	if (dp[ind][col] != -1) {
		return dp[ind][col];
	}
	int up_col = col / 4;
	int down_col = col % 4;

	lint ret = 0;
	if (dom[0][ind] == dom[1][ind]) {
		for (int i = 1; i <= 3; i++) {
			if (i != up_col && i != down_col) {
				ret += recursion(ind + 1, (i * 4) + i);
				ret %= MOD;
			}
		}
	}
	else {
		for (int i = 1; i <= 3; i++) {
			if (i != up_col) {
				for (int j = 1; j <= 3; j++) {
					if (j != down_col && j != i) {
						ret += recursion(ind + 2, (i * 4) + j);
						ret %= MOD;
					}
				}
			}
		}
	}
	ret %= MOD;
	dp[ind][col] = ret;
	return ret;
}
