/**
* ax + by = result
*/
template <typename T>
T extendedGcd(T a, T b, T& x, T& y) {
    if (a == 0) {
        x = 0;
        y = 1;
        return b;
    }
    T d = extendedGcd(b % a, a, y, x);
    x -= (b / a) * y;
    return d;
}

template <typename T>
class Zn {
public:
    Zn(): value(0) {
    }

    Zn(int64_t value): value(value) {
        int x = static_cast<int>(value % mod());
        if (x < 0) {
            x += mod();
        }
        this->value = x;
    }

    template <typename U>
    static Zn valueOf(U value) {
        int x = static_cast<int>(value % mod());
        if (x < 0) {
            x += mod();
        }
        return Zn(x);
    }

    static Zn rawValueOf(int value) {
        SPCPPL_ASSERT(value >= 0 && value < mod());
        return Zn(value);
    }

    template <typename U>
    Zn& operator=(U rhs) {
        return *this = Zn::valueOf(rhs);
    }


    Zn& operator+=(const Zn& rhs) {
        value += rhs.value;
        if (value >= mod()) {
            value -= mod();
        }
        return *this;
    }

    template <typename U>
    Zn& operator+=(U rhs) {
        return *this += Zn::valueOf(rhs);
    }

    Zn& operator-=(const Zn& rhs) {
        value -= rhs.value;
        if (value < 0) {
            value += mod();
        }
        return *this;
    }

    template <typename U>
    Zn& operator-=(U rhs) {
        return *this -= Zn::valueOf(rhs);
    }

    Zn& operator*=(const Zn& rhs) {
        long long result = static_cast<int64_t>(value) * static_cast<int64_t>(rhs.value);
        value = static_cast<int>(result % mod());
        return *this;
    }

    template <typename U>
    Zn& operator*=(U rhs) {
        return *this *= Zn::valueOf(rhs);
    }

    Zn operator-() const {
        if (value == 0) {
            return *this;
        }
        else {
            return Zn(mod() - value);
        }
    }

    Zn& operator/=(const Zn& rhs) {
        return *this *= rhs.inversed();
    }

    template <typename U>
    Zn& operator/=(U rhs) {
        return *this /= Zn::valueOf(rhs);
    }

    Zn inv() const {
        return inversed();
    }

    inline Zn inversed() const {
        SPCPPL_ASSERT(value != 0);

        int x, y;
        int gcd = extendedGcd(value, mod(), x, y);
        (void) gcd;
        SPCPPL_ASSERT(gcd == 1);

        if (x < 0) {
            x += mod();
        }
        return Zn(x);
    }

    template <typename U>
    friend std::ostream& operator<<(std::ostream&, const Zn<U>& zn);

    template <typename U>
    friend std::istream& operator>>(std::istream&, Zn<U>& zn);

    template <typename U>
    friend bool operator==(const Zn<U>& lhs, const Zn<U>& rhs);

    int intValue() const {
        return value;
    }

    operator int64_t() const {
        return value;
    }

    constexpr static int mod() {
        return T::value;
    }

private:
    int value;

    template <int N = T::value>
    static constexpr bool correct_or_runtime(int) {
        return N > 0 && N <= (1 << 30);
    }
    static constexpr bool correct_or_runtime(...) {
        return true;
    }
    static_assert(
            std::is_same<typename std::decay<decltype(T::value)>::type, int>::value,
            "T::value must be int"
    );
    static_assert(correct_or_runtime(0), "Mod has to be positive integer up to 1 << 30");
};

