using namespace std;

class DColoringDominoes {
public:
	void solve(std::istream& in, std::ostream& out) {
        int n;
        in >> n;
        vector<str> S(2);
        in >> S;
        vector<Zn7> dp(n + 1);
        dp[0] = 1;
        FOR(i, 1, n + 1) {
            dp[i] = dp[i - 1];
            if (S[0][i - 1] == S[1][i - 1]) {
                if (i == 1) {
                    dp[i] *= 3;
                } else if (S[0][i - 2] == S[1][i - 2]) {
                    dp[i] *= 2;
                }
            } else {
                if (i == 1) {
                    dp[i] *= 6;
                } else if (S[0][i - 2] != S[0][i - 1]) {
                    if (S[0][i - 2] == S[1][i - 2]) {
                        dp[i] *= 2;
                    } else {
                        dp[i] *= 3;
                    }
                }
            }
        }
        Zn7 res = dp[n];
        out << res << '\n';
	}

	void setup() {}
};


int main() {
    std::ios_base::sync_with_stdio(false);
	DColoringDominoes solver;
    solver.setup();
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	in.tie(nullptr);
    out << std::fixed;
    out.precision(20);
	solver.solve(in, out);
	return 0;
}

