#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll N = 1e6 + 5, mod = 1e9 + 7;

#define temptts template <class T, class... Ts>
temptts int add(T f) { return f; } temptts int add(T f, Ts... ts) { return (f + add(ts...)) % mod; }
temptts int sub(T f) { return f; } temptts int sub(T f, Ts... ts) { return (f - sub(ts...) + 1ll * mod * mod) % mod; }
temptts int mul(T f) { return f; } temptts int mul(T f, Ts... ts) { return (1ll * f * mul(ts...)) % mod; }

int n;
char s[N], t[N];
int dp[N][3], f[N][3][3];

int32_t main() { cin.tie(0)->sync_with_stdio(0);
  cin >> n;
  for (int i = 1; i <= n; i++) {
    cin >> s[i];
  }
  for (int i = 1; i <= n; i++) {
    cin >> t[i];
  }
  for (int i = 1; i <= n; i++) {
    if (s[i] == t[i]) {
      if (i == 1) {
        dp[i][0] = dp[i][1] = dp[i][2] = 1;
        continue;
      }
      dp[i][0] = dp[i - 1][1] + dp[i - 1][2] + f[i - 1][1][2] + f[i - 1][2][1];
      dp[i][1] = dp[i - 1][0] + dp[i - 1][2] + f[i - 1][0][2] + f[i - 1][2][0];
      dp[i][2] = dp[i - 1][0] + dp[i - 1][1] + f[i - 1][0][1] + f[i - 1][1][0];
    } else if (s[i] == s[i - 1]) {
      int c = i;
      if (i == 2) {
        for (int i = 0; i < 3; i++) {
          for (int j = 0; j < 3; j++) {
            if (i == j) continue;
            f[c][i][j] = 1;
          }
        }
        continue;
      }
      for (int i = 0; i < 3; i++) {
        for (int j = 0; j < 3; j++) {
          if (i == j) continue;
          int k = i ^ j ^ 0 ^ 1 ^ 2;
          f[c][i][j] = dp[c - 2][k];
          for (int u = 0; u < 3; u++) {
            for (int v = 0; v < 3; v++) {
              if (u == v) continue;
              if (u != i && v != j) {
                f[c][i][j] = add(f[c][i][j], f[c - 2][u][v]);
              }
            }
          }
        }
      }
    }
  }
  int ans = 0;
  if (s[n] == t[n]) for (int i = 0; i < 3; i++) {
    ans = add(ans, dp[n][i]);
  } else {
    for (int i = 0; i < 3; i++) {
      for (int j = 0; j < 3; j++) {
        if (i == j) continue;
        ans = add(ans, f[n][i][j]);
      }
    }
  }
  cout << ans;
}

