  if(s1[0] == s2[0]) dp[1] = 3;
  else dp[1] = 6;
  for(int i = 1; i < n; i++){
    if(s1[i-1] == s1[i] && s2[i-1] == s2[i]){
      dp[i+1] = dp[i];
      continue;
    }
    if(s1[i-1] == s2[i-1]){
      //X->X
      if(s1[i] == s2[i]){
        dp[i+1] = dp[i] * 2;
      }
      //X->Y
