      //Y->X
      if(s1[i] == s2[i]){
        dp[i+1] = dp[i];
      }
      //Y->Y
      else {
        dp[i+1] = dp[i] * 3;
      }
    }
    dp[i] %= MOD;
  }
  cout << dp[n]%MOD << endl;

