#include <bits/stdc++.h>
using namespace std;
using Pair = pair<int64_t, int64_t>;
constexpr int64_t kInf = INT64_MAX / 2L;

// std::cout << std::setprecision(20) << 1.1 << endl;

const int64_t kMod = 1000000007LL;
// const int64_t kMod = 998244353LL;
struct Mint {
  int64_t value;
  Mint(int64_t value = 0LL) : value((value % kMod + kMod) % kMod) {}
  Mint operator-() const {
    return Mint(-value);
  }
  Mint &operator+=(const Mint rhs) {
    if ((value += rhs.value) >= kMod) {
      value -= kMod;
    }
    return *this;
  }
  Mint &operator-=(const Mint rhs) {
    if ((value += kMod - rhs.value) >= kMod) {
      value -= kMod;
    }
    return *this;
  }
  Mint &operator*=(const Mint rhs) {
    (value *= rhs.value) %= kMod;
    return *this;
  }
  Mint operator+(const Mint rhs) const {
    return Mint(*this) += rhs;
  }
  Mint operator-(const Mint rhs) const {
    return Mint(*this) -= rhs;
  }
  Mint operator*(const Mint rhs) const {
    return Mint(*this) *= rhs;
  }
  Mint Pow(int64_t p) const {
    if (p == 0LL) {
      return 1LL;
    } else if (p < 0LL) {
      return Pow(-p).Pow(kMod - 2LL);
    }
    Mint temp = Pow(p >> 1LL);
    temp *= temp;
    if (p & 1LL) {
      temp *= (*this);
    }
    return temp;
  }
  Mint Inv() const {
    return Pow(kMod - 2LL);
  }
  Mint &operator/=(const Mint a) {
    return *this *= a.Inv();
  }
  Mint operator/(const Mint a) const {
    return Mint(*this) /= a;
  }
};

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int64_t N;
  string S1, S2;
  cin >> N >> S1 >> S2;
  pair<Mint, Mint> current;
  if (S1[0] == S2[0]) {
    current.first = 3;
    current.second = 0;
  } else {
    current.first = 0;
    current.second = 6;
  }
  for (int64_t i = 1; i < N; ++i) {
    pair<Mint, Mint> previous;
    swap(current, previous);
    if (S1[i] == S2[i]) {
      current.first = previous.first * 2 + previous.second;
      current.second = 0;
    } else {
      if (S1[i] != S1[i - 1]) {
        current.first = 0;
        current.second = previous.first * 2 + previous.second * 3;
      } else {
        current = previous;
        // DO NOTHING
      }
    }
    // cerr << "i=" << i << ": " << current.first.value << ", " << current.second.value << endl;
  }
  cout << (current.first + current.second).value << endl;
  return 0;
}

