long long mod = 1e9 + 7;
long long dp[55][5][5];

int main()
{
//    freopen(FILE".in", "r", stdin);
//    freopen(FILE".out", "w", stdout);
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    int n;
    cin >> n;
    string s[2];
    cin >> s[0] >> s[1];
    vector<bool> type;
    for(int i = 0; i < n; i++)
    {
        if(s[0][i] == s[1][i])
            type.pb(0);
        else
            type.pb(1), i++;
    }
    if(type[0])
    {
        for(int i = 0; i < 3; i++)
        {
            for(int j = 0; j < 3; j++)
            {
                if(i == j)
                    continue;
                dp[0][i][j] = 1;
            }
        }
    }
    else
    {
        for(int i = 0; i < 3; i++)
            dp[0][i][i] = 1;
    }
    for(int i = 1; i < type.size(); i++)
    {
        if(type[i])
        {
            for(int a = 0; a < 3; a++)
            {
                for(int b = 0; b < 3; b++)
                {
                    if(a == b)
                        continue;
                    for(int c = 0; c < 3; c++)
                    {
                        for(int d = 0; d < 3; d++)
                        {
                            if(a == c || b == d)
                                continue;
                            dp[i][a][b] += dp[i - 1][c][d];
                            if(dp[i][a][b] >= mod)
                                dp[i][a][b] -= mod;
                        }
                    }
                }
            }
        }
        else
        {
            for(int a = 0; a < 3; a++)
            {
                for(int b = 0; b < 3; b++)
                {
                    for(int c = 0; c < 3; c++)
                    {
                        if(a == b || a == c)
                            continue;
                        dp[i][a][a] += dp[i - 1][b][c];
                        if(dp[i][a][b] >= mod)
                            dp[i][a][b] -= mod;
                    }
                }
            }
        }
    }
    long long ans = 0;
    for(int i = 0; i < 3; i++)
    {
        for(int j = 0; j < 3; j++)
        {
            ans += dp[type.size() - 1][i][j];
            if(ans >= mod)
                ans -= mod;
        }
    }
    cout << ans;
    return 0;
}

