      }
    }
  }
  else{
    if(tmp2!=-1){
      for(int i=0; i<3; ++i){
        if(i!=tmp2&&i!=c1)
          res+=dp(x+1, i, tmp2);
        res%=mod;
      }
    }
    else{
      for(int i=0; i<3; ++i){
        if(i==c1)
          continue;
        for(int j=0; j<3; ++j){
          if(i==j||j==c2)
            continue;
          res+=dp(x+1, i,j);
          res%=mod;
        }
      }
    }
  }
  res%=mod;
  mem[x][c1][c2]=res;
  return res;
}
