using namespace std;

const int mod = (int)1e9 + 7;

const int MAXN = 60;

int dp[MAXN][4][4];

int main() {
#ifdef __APPLE__
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif

    int n;
    cin >> n;
    string s[2];
    cin >> s[0] >> s[1];
    s[0] = "." + s[0];
    s[1] = "." + s[1];
    dp[0][3][3] = 1;
    for (int i = 1; i <= n; ++i) {
        for (int c0 = 0; c0 < 3; ++c0) {
            for (int c1 = 0; c1 < 3; ++c1) {
                if (s[0][i] == s[0][i - 1] &&
                    s[1][i] == s[1][i - 1]) {
                    dp[i][c0][c1] = dp[i - 1][c0][c1];
                } else if (s[0][i] == s[0][i - 1] &&
                           s[1][i] != s[1][i - 1]) {
                    for (int j = 0; j < 3; ++j) {
                        if (c0 != c1 && c1 != j)
                            (dp[i][c0][c1] += dp[i - 1][c0][j]) %= mod;
                    }
                } else if (s[0][i] != s[0][i - 1] &&
                           s[1][i] == s[1][i - 1]) {
                    for (int j = 0; j < 3; ++j) {
                        if (c0 != c1 && c0 != j)
                            (dp[i][c0][c1] += dp[i - 1][j][c1]) %= mod;
                    }
                } else if (s[0][i] != s[0][i - 1] &&
                           s[1][i] != s[1][i - 1] &&
                           s[0][i] != s[1][i]) {
                    for (int j = 0; j < 4; ++j) {
                        for (int k = 0; k < 4; ++k) {
                            if (c0 != c1 && c0 != j && c1 != k)
                                (dp[i][c0][c1] += dp[i - 1][j][k]) %= mod;
                        }
                    }
                } else {
                    for (int j = 0; j < 4; ++j) {
                        for (int k = 0; k < 4; ++k) {
                            if (c0 == c1 && c0 != j && c1 != k)
                                (dp[i][c0][c1] += dp[i - 1][j][k]) %= mod;
                        }
                    }
                }
            }
        }
    }
    int ans = 0;
    for (int i = 0; i < 3; ++i) {
        for (int j = 0; j < 3; ++j) {
            (ans += dp[n][i][j]) %= mod;
        }
    }
    printf("%d", ans);

    return 0;
}

