bool solve(int testNumber) {
	int n;
	if (!(cin >> n)) return false;
	vector<string> S(2);
	for (string &str: S) cin >> str;
	vector<bool> hor;
	for (int i = 0; i < n; i++) {
		if (S[0][i] == S[1][i]) hor.push_back(false);
		else {
			hor.push_back(true);
			i++;
		}
	}
	n = hor.size();
	vector<int> dp(n + 1);
	dp[0] = 1;
	for (int i = 1; i <= n; i++) {
		bool h = hor[i - 1], hh = i > 1 ? hor[i - 2] : false;
		int mul;
		if (h) {
			if (i == 1) mul = 6;
			else if (hh) mul = 3;
			else mul = 2;
		} else {
			if (i == 1) mul = 3;
			else if (hh) mul = 1;
			else mul = 2;
		}
		dp[i] = (lint)dp[i - 1] * mul % MOD;
	}
	int ans = dp.back();
	printf("%d\n", ans);
	return true;
}

