		for(int k = 0; k < 3; ++k) if(c.find(k) == c.end()) {
			mp[S[i][j]] = k;
			color(1-i, j + i %2, l, r, S, mp, res);
			mp.erase(S[i][j]);
		}
	} else {
		color(1-i, j + (i % 2), l, r, S, mp, res);
