ll solve(int N,string& s1,string& s2) {
    vector<int> a;
    for (int i=0; i<N; ) {
        if (s1[i] == s2[i]) {
            a.pb(1);
            ++i;
        } else {
            a.pb(2);
            i+=2;
        }
    }

    int M = a.size();
    ll pat = (a[0] == 1)? 3 : 6; // 3C1 x 1!, 3C2 x 2!
    for (int i=1; i<M; ++i) {
        if (a[i-1] == 1) {
            if (a[i] == 1) {
                // 1 - 1 他の色ならOK
                pat = MUL(pat, 2); // 2C1 x 1!
            } else {
                // 1 - 2
                pat = MUL(pat, 2); // 2C2 x 2!
            }
        } else {
            if (a[i] == 1) {
                // 2 - 1
                pat = pat; // 3C1 x 1!
            } else {
                // 2 - 2
                pat = MUL(pat, 3); // 3C2x2! - 1 - 2
            }
        }
    }
    return pat;
}

