        for(int i = 0; i < n / 2 - 1; ++i){
            ans *= 3;
            ans %= mod;
        }
        cout << ans << endl;
        return 0;
    }
    ull ans = 1;
    for(ull i = 0; i < v.size() - 1; ++i){
        ull haba = (v[i + 1] - v[i] - 1) / 2;
        if(haba){
            ans *= 2 * (ull)pow(3, haba - 1) % mod;
            ans %= mod;
        }else{  
            ans *= 2;
            ans %= mod;
        }
    }
    cout << 3 * ans  / (s1[0] == s2[0] ? 2 : 1) % mod << endl;
    return 0;
}

