const int MAX_N = 55, MOD = 1e9 + 7;

int n;
string s, t;

bool usedStates[MAX_N][4][4];
int dp[MAX_N][4][4];

int Solve(int colInd, int upColor, int downColor) {
	if(colInd == n) {
		return 1;
	}
	else if(usedStates[colInd][upColor][downColor]) {
		return dp[colInd][upColor][downColor];
	}

	bool colors[4] = {1, 1, 1, 1};
	colors[upColor] = 0;
	colors[downColor] = 0;

	int ans = 0;
	if(s[colInd] == t[colInd]) {
		for(int i = 1; i <= 3; i++) {
			if(colors[i]) {
				ans = (1ll * ans + 1ll * Solve(colInd + 1, i, i)) % MOD;
			}
		}
	}
	else {
		for(int i = 1; i <= 3; i++) {
			for(int j = 1; j <= 3; j++) {
				if(i == j || i == upColor|| j == downColor) {
					continue;
				}

				ans = (1ll * ans + 1ll * Solve(colInd + 2, i, j)) % MOD;
			}
		}
	}

	usedStates[colInd][upColor][downColor] = true;
	dp[colInd][upColor][downColor] = ans;

	return ans;
}

