    if(A[0] == 2) ans = 6;
    for(int i = 1; i < count; i++){
        if(A[i-1] == 1 && A[i] == 1) ans *= 2;
        if(A[i-1] == 1 && A[i] == 2) ans *= 2;
        if(A[i-1] == 2 && A[i] == 1) ans *= 1;
        if(A[i-1] == 2 && A[i] == 2) ans *= 3;
        ans = ans % mod;
    }
    cout << ans << endl;
    return 0;
}

