char G[52][2];

bool check(int n, int a, int b, int c, int d) {
	if (G[n - 1][0] == G[n - 1][1] && a != b) return 0;
	if (G[n - 1][0] != G[n - 1][1] && a == b) return 0; 
	if (G[n][0] == G[n][1] && c != d) return 0;
	if (G[n][0] != G[n][1] && c == d) return 0;
	if (G[n - 1][0] == G[n][0] && a != c) return 0;
	if (G[n - 1][0] != G[n][0] && a == c) return 0;
	if (G[n - 1][1] == G[n][1] && b != d) return 0;
	if (G[n - 1][1] != G[n][1] && b == d) return 0;
	return 1;
}

int main() {
    ios::sync_with_stdio(false);
    int N;
    cin >> N;
    for (int i = 0;i < N;i++) cin >> G[i][0];
    for (int i = 0;i < N;i++) cin >> G[i][1];
    ll MOD = 1E9 + 7;
    ll DP[53][9];
    memset(DP, 0, sizeof(DP));
    if (G[0][0] == G[0][1]) {
    	DP[0][0] = 1; // 00
    	DP[0][4] = 1; // 11
    	DP[0][8] = 1; // 22
    }
    else {
    	DP[0][1] = 1; // 01
    	DP[0][2] = 1; // 02
    	DP[0][3] = 1; // 10
    	DP[0][5] = 1; // 11
    	DP[0][6] = 1; // 20
    	DP[0][7] = 1; // 21
    }
    for (int i = 1;i < N;i++) {
    	for (int a = 0;a < 3;a++) {
    		for (int b = 0;b < 3;b++) {
    			for (int c = 0;c < 3;c++) {
    				for (int d = 0;d < 3;d++) {
    					if (check(i, a, b, c, d)) {
    						DP[i][c * 3 + d] += DP[i - 1][a * 3 + b];
    						DP[i][c * 3 + d] %= MOD;
    					}
    				}
    			}
    		}
    	}
    }
    ll sol = 0;
    for (int i = 0;i < 9;i++) {
    	sol += DP[N - 1][i];
    	sol %= MOD;
    }
    cout << sol << endl;
    return 0;
}

