                else
                    dp[i+1] = 2 * dp[i-1] % MOD;
            }
            i++;
        }
        else{
            if(s1[i-1] != s2[i-1])
                dp[i] = dp[i-1];
            else{
                if(i == 1)
                    dp[i] = 3;
                else
                    dp[i] = 2 * dp[i-1] % MOD;
            }
        }
    }
    cout << dp[N] << endl;

    return 0;
}

