int64_t dp[60][3][3];

int64_t Add(int64_t a, int64_t b) {
  a += b;
  if (a > MOD) {
    a -= MOD;
  }
  return a;
}

int main() {
  int N;
  string S1, S2;
  cin >> N >> S1 >> S2;

  vector<int> splitIndices;
  for (int i = 1; i < N; i++) {
    if (S1[i - 1] != S1[i]) {
      splitIndices.push_back(i);
    }
  }
  splitIndices.push_back(N);

  memset(dp, 0, sizeof(dp));

  int a = splitIndices[0];
  if (a == 1) {
    for (int c = 0; c < 3; c++) {
      dp[1][c][c] = 1;
    }
  } else {
    for (int colorUp = 0; colorUp < 3; colorUp++) {
      for (int colorDown = 0; colorDown < 3; colorDown++) {
        if (colorDown == colorUp) continue;
        dp[2][colorUp][colorDown] = 1;
      }
    }
  }

  for (int i = 1; i < splitIndices.size(); i++) {
    int interval = splitIndices[i] - splitIndices[i - 1];

    if (interval == 1) {
      for (int prevColorUp = 0; prevColorUp < 3; prevColorUp++) {
        for (int prevColorDown = 0; prevColorDown < 3; prevColorDown++) {
          for (int c = 0; c < 3; c++) {
            if (c == prevColorUp or c == prevColorDown) continue;
            dp[splitIndices[i]][c][c] =
                Add(dp[splitIndices[i]][c][c],
                    dp[splitIndices[i - 1]][prevColorUp][prevColorDown]);
          }
        }
      }
    } else {
      for (int prevColorUp = 0; prevColorUp < 3; prevColorUp++) {
        for (int prevColorDown = 0; prevColorDown < 3; prevColorDown++) {
          for (int colorUp = 0; colorUp < 3; colorUp++) {
            if (colorUp == prevColorUp) continue;
            for (int colorDown = 0; colorDown < 3; colorDown++) {
              if (colorDown == prevColorDown) continue;
              if (colorDown == colorUp) continue;
              dp[splitIndices[i]][colorUp][colorDown] =
                  Add(dp[splitIndices[i]][colorUp][colorDown],
                      dp[splitIndices[i - 1]][prevColorUp][prevColorDown]);
            }
          }
        }
      }
    }
  }

  int64_t total = 0;
  for (int colorUp = 0; colorUp < 3; colorUp++) {
    for (int colorDown = 0; colorDown < 3; colorDown++) {
      total = Add(total, dp[N][colorUp][colorDown]);
    }
  }
  printf("%ld\n", total);

  return 0;
}

