int dfs(int n, int c1, int c2)
{
    if (dp[n][c1][c2] != -1)
        return dp[n][c1][c2];
    if (n == 0) {
        return 1;
    }
    long long ans = 0;
    if (s1[n - 1] == s2[n - 1]) {
        for(int c = 1; c <= 3; ++ c) {
            if (c != c1 && c != c2) {
                ans += dfs(n - 1, c, c);
            }
        }
    } else {
        for(int nc1 = 1; nc1 <= 3; ++ nc1) {
            if (nc1 == c1) continue;
            for(int nc2 = 1; nc2 <= 3; ++ nc2) {
                if (nc2 == c2 || nc2 == nc1) continue;
                ans += dfs(n - 2, nc1, nc2);
            }
        }
    }
    dp[n][c1][c2] = ans % MOD;
    return ans % MOD;
} 

