map<int, ll> m;

ll solve(int i, bool a1, bool a2, bool b1, bool b2, bool c1, bool c2)
{
	if (m[a1 + 2 * a2 + 4 * b1 + 8 * b2 + 16 * c1 + 32 * c2 + i*64] != 0)
		return m[a1 + 2 * a2 + 4 * b1 + 8 * b2 + 16 * c1 + 32 * c2 + i*64];

	if (i >= n)
		return 1;

	ll res = 0;
	if (s1[i] == s2[i])
	{
		if (a1&&a2)
			res +=  solve(i + 1, 0, 0, 1, 1, 1, 1);
		if (b1&&b2)
			res +=  solve(i + 1, 1, 1, 0, 0, 1, 1);
		if (c1&&c2)
			res +=  solve(i + 1, 1, 1, 1, 1, 0, 0);		
	}
	else
	{
		if (a1&&b2)
			res +=  solve(i + 2, 0, 1, 1, 0, 1, 1);

		if (a1&&c2)
			res += solve(i + 2, 0, 1, 1, 1, 1, 0);

		if (b1&&a2)
			res += solve(i + 2, 1, 0, 0, 1, 1, 1);

		if (b1&&c2)
			res += solve(i + 2, 1, 1, 0, 1, 1, 0);

		if (c1&&a2)
			res += solve(i + 2, 1, 0, 1, 1, 0, 1);

		if (c1&&b2)
			res += solve(i + 2, 1, 1, 1, 0, 0, 1);

	}
	m[a1 + 2 * a2 + 4 * b1 + 8 * b2 + 16 * c1 + 32 * c2 + i*64] = res%mod;
	return res%mod;
}

