int64_t sol() {
   auto is_vert = s1[1] == s2[1];
   ar[1] = ar[2] = is_vert ? 3 : 6;
   int col = is_vert ? 2 : 3;

   for (; col <= n; col++)
   {
      const auto is_ve2 = s1[col] == s2[col];
      if (is_vert) {// |
         if (is_ve2) {// ||
            ar[col] = (ar[col - 1] << 1) % mod;
