			dp[i][j].clear();
			dp[i][j].resize(N,0);
		}
	}
	if (S[0][0] == S[1][0]) {
		for (int c = 0; c < 3; c++) {
			dp[c][c][0] = 1;
		}
	}
	else {
		for (int c0 = 0; c0 < 3; c0++) {
			for (int c1 = 0; c1 < 3; c1++) {
				if (c0 == c1)continue;
				dp[c0][c1][0] = 1;
			}
		}
