			for (int c = 0; c < 3; c++) {
				for (int c0 = 0; c0 < 3; c0++) {
					for (int c1 = 0; c1 < 3; c1++) {
						if (c0 == c || c1 == c)continue;
						dp[c][c][n] += dp[c0][c1][n - 1];
					}
				}
			}
		}
		else if (S[0][n] == S[0][n - 1] && S[1][n] == S[1][n - 1]) {
			for (int c1 = 0; c1 < 3; c1++) {
				for (int c2 = 0; c2 < 3; c2++) {
					if (c1 == c2)continue;
					dp[c1][c2][n] = dp[c1][c2][n - 1];
				}
			}
		}
		else if (S[0][n] != S[0][n - 1] && S[1][n] == S[1][n - 1]) {
			for (int c1 = 0; c1 < 3; c1++) {
				for (int c2 = 0; c2 < 3; c2++) {
					for (int c = 0; c < 3; c++) {
						if (c == c1 || c == c2)continue;
						dp[c1][c2][n] = dp[c][c2][n - 1];
					}
				}
			}
		}
		else if (S[0][n] == S[0][n - 1] && S[1][n] != S[1][n - 1]) {
			for (int c1 = 0; c1 < 3; c1++) {
				for (int c2 = 0; c2 < 3; c2++) {
					for (int c = 0; c < 3; c++) {
						if (c == c1 || c == c2)continue;
						dp[c1][c2][n] = dp[c1][c][n - 1];
					}
				}
			}
		}
		else {
			for (int c1 = 0; c1 < 3; c1++) {
				for (int c2 = 0; c2 < 3; c2++) {
					for (int c11 = 0; c11 < 3; c11++) {
						for (int c22 = 0; c22 < 3; c22++) {
							if (c11 == c1 || c22 == c2)continue;
							dp[c1][c2][n] += dp[c11][c22][n - 1];
						}
					}
				}
			}
		}
		for (int c1 = 0; c1 < 3; c1++) {
			for (int c2 = 0; c2 < 3; c2++) {
				dp[c1][c2][n] %= MOD;
			}
		}
	}
	long long ans = 0;
	for (int c1 = 0; c1 < 3; c1++) {
		for (int c2 = 0; c2 < 3; c2++)ans += dp[c1][c2][N - 1];
	}
	ans %= MOD;
	cout << ans << endl;
	return;
}

