            if (!((pmask>>c)&1)) {
                ans += Solve(pos+1, {c});
                ans %= MODD;
            }
        }
        return dp[pos][pcolors]=ans;
    } else {
        ll ans = 0;
        for(int c1=0;c1<3;c1++)
            for(int c2=0;c2<3;c2++) {
