int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	int N;
	cin >> N;
	cin >> b[0] >> b[1];

	dp[0][3][3] = 1;
	for(int i = 0; i < N; i++) {
		for(int j = 0; j < 4; j++) { // 上の左
			for(int k = 0; k < 4; k++) { // 下の左
				ll num = dp[i][j][k];
				if(num == 0) continue;
				if(b[0][i] == b[1][i]) {
					for(int c = 0; c < 3; c++) {
						if(c == j || c == k) continue;
						dp[i + 1][c][c] += num;
						dp[i + 1][c][c] %= MOD;
					}
				}
				else {
					for(int u = 0; u < 3; u++) {// 上に塗る色
						if(i - 1 >= 0 && b[0][i - 1] == b[0][i]){
							if(j != u) continue;
						}
						else if(j == u) continue;
						for(int d = 0; d < 3; d++) { // 下に塗る色
							if(i - 1 >= 0 && b[1][i - 1] == b[1][i]){
								if(k != d) continue;
							}
							else if(k == d) continue;

							if(u == d) continue;
							dp[i + 1][u][d] += num;
							dp[i + 1][u][d] %= MOD;
						}
					}
				}
			}
		}
	}

	ll ans = 0;
	for(int j = 0; j < 4; j++) { // 上の左
		for(int k = 0; k < 4; k++) { // 下の左
			ans += dp[N][j][k];
			ans %= MOD;
		}
	}
	cout << ans << endl;
}

