int get_dp(int pos , int i  , int j){
    if( (i == j) != (s[0][pos] == s[1][pos]) ) return 0;
    if(pos == n - 1) return 1; 
    int& res = dp[pos][i][j];
    if(~res)
        return res;
    res = 0; 
    if(s[0][pos] == s[0][pos + 1] && s[1][pos] == s[1][pos + 1]){
        res = (res + get_dp(pos + 1 , i , j)) % mod ;
    }
    else if(s[0][pos] == s[0][pos + 1]){
        for(int nj = 0 ; nj < 3 ; ++nj){
            if(nj == j) continue ;
            res = (res + get_dp(pos + 1 , i , nj)) % mod ;
        }            
    }
    else if(s[1][pos] == s[1][pos + 1]){
        for(int ni = 0 ; ni < 3 ; ++ni){
            if(ni == i) continue ;
            res = (res + get_dp(pos + 1 , ni , j)) % mod;
        }            
    }
    else{
        for(int ni = 0 ; ni < 3 ; ++ni){
            for(int nj = 0 ; nj < 3 ; ++nj){
                if(i == ni || j == nj) continue ;
                res = (res + get_dp(pos + 1 , ni , nj)) % mod;
            }    
        }   
    }
    return res;
}

