void solve(){
	const int STARTING = -1;
	const int HORIZONTAL = 0;
	const int VERTICAL = 1;
	int prev_state = STARTING;
	int state = STARTING;
	int index = 0;
	while(index<N){
		if(S1[index]==S2[index]){
			state = VERTICAL;
			index++;
		}else{
			state = HORIZONTAL;
			index += 2;
		}

		if(prev_state==STARTING){
			if(state==HORIZONTAL){
				ans *= 6LL;
				ans %= mod;
			}else{
				ans *= 3LL;
				ans %= mod;
			}
		}else{
			if(prev_state==VERTICAL && state==HORIZONTAL){
				ans *= 2LL;
				ans %= mod;
			}else if(prev_state==VERTICAL && state==VERTICAL){
				ans *= 2LL;
				ans %= mod;
			}else if(prev_state==HORIZONTAL && state==HORIZONTAL){
				ans *= 3LL;
				ans %= mod;
			}
		}
		prev_state = state;
	}
}

