}
ll LCM(ll a, ll b){
    return a/GCD(a,b)*b;
}
int main(){
    int N;
    string S1,S2;
    cin>>N>>S1>>S2;
    ll ans=3;
    ll mod=1e9+7;
    //
    bool p=false;
    if(S1[0]==S1[1]) p=true;
    if(p) ans*=2;
    rep(i,N-1){
        if(p&&i==0) continue;
        if(S1[i+1]==S2[i+1]){ //次のタイルが1x2
            if(S1[i]==S2[i]){ //現在のタイルが1x2
                ans*=2;
            }else{ //現在のタイルが2x1
                ans*=1;
            }
        }else{ //次のタイルが2x1
            if(S1[i]==S2[i]){
                ans*=2;
            }else{
                ans*=3;
            }
            i++;
        }
        ans%=mod;
    }
    cout<<ans<<endl;
}

