long long calc(int index, int num_c, int mode){
	if(index == n){
		return 1;
	}
	long long ans = 1;
	if(s1.at(index) == s2.at(index)){
		if(mode == 1){
			ans = (calc(index + 1, 2, 0)) % m;	
		}
		else{
			ans = (num_c * calc(index + 1, 2, 0)) % m;
		}
	}
	else{
		int x = 2;
		if(num_c == 3){
			x = 6;
		}
		if(mode == 1){
			x -= 3;
		}
		ans = (x * calc(index + 2, 3, 1)) % m;

	}
	return ans;
}
