#include<cstdio>

#define MOD 1000000007

using ll=long long;


int main(void)
{
	int n;
	char s[2][60];

	while(scanf("%d%s%s", &n, s[0], s[1])==3)
	{
		ll ans=1;
		int x=0;
		int is_vertical=-1;

		for(;;)
		{
			if(s[0][x]==s[1][x])
			{
				switch(is_vertical)
				{
					case  1: ans=(ans*2)%MOD; break;
					case  0: break;
					case -1: ans=3; break;
				}
				x++;
				is_vertical=1;
			}
			else
			{
				switch(is_vertical)
				{
					case  1: ans=(ans*2)%MOD; break;
					case  0: ans=(ans*3)%MOD; break;
					case -1: ans=6; break;
				}
				x+=2;
				is_vertical=0;
			}

			if(x>=n) break;
		}
		printf("%lld\n", ans);
	}
	return 0;
}

