using namespace std;
typedef long long int lint;

int main()
{
	lint n, mod = 1000000007;
	string s[2];
	cin >> n;
	cin >> s[0] >> s[1];
	lint N = s[0].size();

	lint state = 0, pos = 0, pattern = 1;

	while (pos < N) {
		//縦
		if (s[0][pos] == s[1][pos]) {
			if (state == 0) {
				pattern *= 3;
				pattern %= mod;
			}
			else if (state == 1) {
				pattern *= 2;
				pattern %= mod;
			}

			state = 1;
			pos++;
		}
		//横
		else {
			if (state == 0) {
				pattern *= 6;
				pattern %= mod;
			}
			else if (state == 1) {
				pattern *= 2;
				pattern %= mod;
			}
			else {
				pattern *= 3;
				pattern %= mod;
			}

			state = 2;
			pos += 2;
		}
	}

	cout << pattern << endl;

	return 0;
}

