int main() {
    ios::sync_with_stdio(false);
    cin.tie(NULL);


    int n;
    cin >> n;
    cin.ignore(); // ignore newline

    for (int i = 0; i < 2; ++i) {
        cin >> mat[i] + 1;
        cin.ignore();
    }

    D[1] = 3;

    if (mat[1][1] != mat[0][1]) {
        D[1] <<= 1;
    }

    const int MOD = (int)1e9 + 7;

    for (int i = 2; i <= n; ++i) {
        D[i] = D[i - 1];

        if (mat[0][i] == mat[0][i - 1] && mat[1][i] == mat[1][i - 1]) {
            continue;
        }

        if (mat[0][i] == mat[1][i]) { // Vertical
            if (mat[0][i - 1] == mat[1][i - 1]) { // Vertical
                D[i] *= 2LL;
            }
            else { // Horizontal
                D[i] *= 1LL;
            }
        }
        else { // Horizontal
            if (mat[0][i - 1] == mat[1][i - 1]) { // Vertical
                D[i] *= 2LL;
            }
            else { // Horizontal
                D[i] *= 3LL;
            }
        }

        D[i] %= MOD;
    }

    cout << D[n];

    return 0;
}

