using namespace std;

void solve() {
  long N;
  string S1, S2;
  cin >> N >> S1 >> S2;

  vector<string> pattern = {
    "aa", "ab", "ac",
    "ba", "bb", "bc",
    "ca", "cb", "cc",
  };

  unordered_map<string, long> state;
  for (auto p: pattern) {
    if (S1[0] == S2[0] and p[0] == p[1]) state[p] = 1;
    if (S1[0] != S2[0] and p[0] != p[1]) state[p] = 1;
  }

  for (long i = 1; i < N; i++) {
    if (S1[i-1] == S1[i]) continue;
    unordered_map<string, long> next_state;
    for (auto p: pattern) for (auto next_p: pattern) {
      if ((S1[i-1] == S2[i-1]) != (p[0] == p[1])) continue;
      if ((S1[i] == S2[i]) != (next_p[0] == next_p[1])) continue;
      if (p[0] == next_p[0]) continue;
      if (p[1] == next_p[1]) continue;
      next_state[next_p] += state[p];
    }
    for (auto it: next_state) next_state[it.first] %= MOD;
    state = next_state;
  }

  long ans = 0;
  for (auto it: state) ans += it.second;
  ans %= MOD;
  cout << ans << endl;
}

int main(void) {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout.precision(12);
  solve();
  return 0;
}

