using namespace std;
long long mod = 1000000007;
int n;
string s1;
string s2;
long long memo[4][4][53];
long long go(int now, int a, int b){
    if(now==n){
        return 1LL;
    }
    if(memo[a][b][now]!=-1LL){
        return memo[a][b][now];
    }
    int f = 3;
    int s = 3;
    if(a!=3 && s1[now]==s1[now-1]){
        f = a;
    }
    if(b!=3 && s2[now]==s2[now-1]){
        s = b;
    }
    long long ret = 0LL;
    for(int c1 = 0; c1<3; c1++){
        if(f!=3 && c1!=f){
            continue;
        }
        if(now>0 && s1[now]!=s1[now-1] && c1==a){
            continue;
        }
        for(int c2 = 0; c2<3; c2++){
            if(s!=3 && c2!=s){
                continue;
            }
            if(s1[now]==s2[now]){
                if(c1!=c2){
                    continue;
                }
            }
            else{
                if(c1==c2){
                    continue;
                }
            }
            if(now>0 && s2[now]!=s2[now-1] && c2==b){
                continue;
            }
            ret += go(now+1,c1,c2);
            ret %= mod;
        }
    }
    memo[a][b][now] = ret;
    return ret;
}
int main() {
    std::ios::sync_with_stdio(false);
    cin.tie(0);
    for(int a = 0; a<4; a++){
        for(int b = 0; b<4; b++){
            for(int c = 0; c<53; c++){
                memo[a][b][c] = -1LL;
            }
        }
    }
    cin >> n >> s1 >> s2;;
    long long ans = go(0,3,3);
    cout << ans << endl;
    return 0;
}

