        for (int i=0; i<9; i++) {
                if ((s1[0] != s2[0]) ^ (i%3 == i/3)) {
                        dp[i][0] = 1;
                } else {
                        dp[i][0] = 0;
                }
        }

        for (int i=1; i<N; i++) {
                if (s1[i] == s1[i-1]) {
                        for (int j=0; j<9; j++)
                                dp[j][i] = dp[j][i-1];
