                                dp[j][i] = 0;
                                if ((s1[i] != s2[i]) ^ (j%3 == j/3)) {
                                        for (int k=0; k<9; k++) {
                                                if (j%3 != k%3 && j/3 != k/3) {
                                                        dp[j][i] += dp[k][i-1];
                                                        dp[j][i] %= MOD;
                                                }
                                        }
                                }
                        }
