          nxt[i][i] += pre[j][k];
          nxt[i][i] %= mod;
        } else {
          rep(i, 3) if (k != i) {
            nxt[i][i] += pre[k][k];
            nxt[i][i] %= mod;
          }
        }
      }
    } else {
      rep(j, 3) rep(k, 3) rep(i, 3) rep(l, 3) {
        if (j != i && k != l && i != l) {
          nxt[i][l] += pre[j][k];
          nxt[i][l] %= mod;
        }
      }
      x++;
    }
    memcpy(pre, nxt, sizeof(nxt));
  }

  ll ans = 0;
  rep(i, 3) rep(j, 3) ans += pre[i][j];
  pr(ans % mod);

  return 0;
}

