            ans%=MOD;
            x++;
            pre=0;
        }
        else{
            if(pre<0) ans=6;
            else if(pre==0) ans*=2;
            else ans*=3;
            ans%=MOD;
            x+=2;
            pre=1;
        }
    }
    cout<<ans<<endl;
}

