			if (a[i-2]==b[i-2]) ans*=2,ans%=MOD;
		}
		else {
			if (a[i-2]!=a[i-1]) {
				if (a[i-2]==b[i-2]) ans*=2,ans%=MOD;
				else ans*=3,ans%=MOD;
			}
		}
	}
	cout<<ans<<endl;
	return 0;
}
