struct zint {
	const lint mod = 1e9 + 7;
	lint value;

	zint(): value() {}

	zint(lint val) {
		value = (val % mod + mod) % mod;
	}

	zint operator +(const zint & other) const {
		return zint(value + other.value);
	}

	zint operator -(const zint & other) const {
		return zint(value - other.value);
	}

	zint operator *(const zint & other) const {
		return zint(value * other.value);
	}

	zint operator +=(const zint & other) {
		this->value = (*this + other).value;
		return *this;
	}

	zint operator -=(const zint & other) {
		this->value = (*this - other).value;
		return *this;
	}

	zint operator *=(const zint & other) {
		this->value = (*this * other).value;
		return *this;
	}

    zint & operator=(zint other) {
        this->value = other.value;
        return *this;
    }

    friend ostream & operator <<(ostream & os, const zint & number) {
        os << number.value;
        return os;
    }

    friend istream & operator >>(istream & is, zint & number) {
        is >> number.value;
        number = zint(number.value);
        return is;
    }
};

