const LL MOD = 1000000007LL;

LL dp[500][20];

LL memo(int idx, int color) {
	if (idx == S1.sz)
		return 1LL;
	LL &ret = dp[idx][color];
	if (ret != -1)
		return ret;

	int c1 = color % 3;
	int c2 = color / 3;
	if (!idx)
		c1 = c2 = -1;
	ret = 0;
	FOR (i1, 3)
		FOR (i2, 3) {
			if (S1[idx] == S2[idx] && i1 != i2)
				continue;
			if (S1[idx] != S2[idx] && i1 == i2)
				continue;
			if (idx && S1[idx] == S1[idx - 1] && i1 != c1)
				continue;
			if (idx && S1[idx] != S1[idx - 1] && i1 == c1)
				continue;
			if (idx && S2[idx] == S2[idx - 1] && i2 != c2)
				continue;
			if (idx && S2[idx] != S2[idx - 1] && i2 == c2)
				continue;
			ret += memo(idx + 1, i2 * 3 + i1);
			if (ret >= MOD)
				ret -= MOD;
		}
	return ret;
}

