const int inf = 1000000007;


string s[2];
int dp[N][3][3];
int n;

void solve() {
    cin >> n;
    cin >> s[0] >> s[1];
    for (int i = 0; i < n; ++i) {
        for (int u = 0; u < 3; ++u) for (int v = 0; v < 3; ++v) {
            if (s[0][i] == s[1][i]) {
                if (u != v) continue;
                if (i == 0) dp[i][u][v] = 1;
                else {
                    rep(lu, 0, 3) rep(lv, 0, 3) if (u != lu && v != lv) {
                        dp[i][u][v] = (dp[i][u][v] + dp[i - 1][lu][lv]) % inf;
                    }
                }
            } else {
                if (u == v) continue;
                if (i == 0) dp[i][u][v] = 1;
                else {
                    rep(lu, 0, 3) rep(lv, 0, 3) {
                        if (s[0][i] == s[0][i - 1] && u != lu) continue;
                        if (s[1][i] == s[1][i - 1] && v != lv) continue;
                        if (s[0][i] != s[0][i - 1] && u == lu) continue;
                        if (s[1][i] != s[1][i - 1] && v == lv) continue;
                        dp[i][u][v] = (dp[i][u][v] + dp[i - 1][lu][lv]) % inf;
                    }
                }
            }
        }
    }
    int res = 0;
    rep(u, 0, 3) rep(v, 0, 3) {
        res = (res + dp[n - 1][u][v]) % inf;
//        cout << u << ' ' << v << ' ' << dp[n - 1][u][v] << '\n';
    }
    cout << res;
}

