		for (int c = 0; c < 3; ++c) {
			dp[0][c][c] = 1;
		}
	} else {
		for (int i = 0; i < 3; ++i) {
			for (int j = 0; j < 3; ++j) {
				if (i != j) {
					dp[0][i][j] = 1;
				}
			}
		}
