                    for (int b = 0; b < 3; ++b) if (a != b) {
                        for (int c = 0; c < 3; ++c) for (int d = 0; d < 3; ++d) {
                            if (a != c && b != d) dp[a][b][j] = add(dp[a][b][j], dp[c][d][j - 2]);
                        }
                    }
                }
            }
        }
    }
    int ans = 0;
    for (int i = 0; i < 3; ++i) for (int j = 0; j < 3; ++j) ans = add(ans, dp[i][j][n]);
    cout << ans << endl;
}

