ll solve(int lo,int hi,int x){
	if(x>=N)return 1;
	if(x>0&&a[0][x]==a[0][x-1])return solve(lo,hi,x+1);

	ll& ret=dp[lo][hi][x];
	if(~ret)return ret;
	ret=0;

	if(a[0][x]==a[1][x]){
		for(int i=1;i<=3;i++){
			if(i==lo)continue;
