	{
		dp[0][0][0] = dp[0][1][1] = dp[0][2][2] = 1;
	}
	else
	{
		dp[0][0][1] = dp[0][0][2] = 
		dp[0][1][0] = dp[0][1][2] = 
		dp[0][2][0] = dp[0][2][1] = 1;
	}

	for (int i = 1; i < N; i ++)
	{
		if (S[0][i] == S[1][i])
		{
			for (int a = 0; a < 3; a ++)
				for (int p = 0; p < 3; p ++)
					for (int q = 0; q < 3; q ++)
					{
						if (p != a && q != a)
							dp[i][a][a] = (dp[i][a][a] + dp[i - 1][p][q]) % MOD;
					}
		}
		else
		{
			for (int a = 0; a < 3; a ++)
				for (int b = 0; b < 3; b ++)
					if (a != b)
