LL dfs(int k, int s, int t) {
    if(memo[k][s][t] != -1) return memo[k][s][t];
    LL sum = 0;
    bool cflag = (c[0][k] == c[1][k]);
    if(cflag && s != t) return 0;
    if(!cflag && s == t) return 0;
    if(k == m-1) return 1;
    for(int i=0;i<3;i++){
        for(int j=0;j<3;j++){
            if(i != s && j != t){
                sum = (sum+dfs(k+1, i, j))%MOD;
            }
        }
    }
    /* if(sum > 0) cout << k << " " << s << " " << t << ":" << sum << endl; */
    return memo[k][s][t] = sum;
}

