        else if (s[0][i] != s[1][i] && s[0][i + 1] == s[1][i + 1]) ans = 2 * ans % MOD;
    }
    for (int i = t + 1; i < n; i++)
    {
        if (s[0][i] == s[1][i] && s[0][i - 1] == s[1][i - 1]) ans = 2 * ans % MOD;
        else if (s[0][i] != s[0][i - 1] && s[0][i] != s[1][i] && s[0][i - 1] != s[1][i - 1]) ans = 3 * ans % MOD;
        else if (s[0][i] != s[1][i] && s[0][i - 1] == s[1][i - 1]) ans = 2 * ans % MOD;
