const int max_n = 52;
const unsigned int mod = 1000000007;

char s[2][max_n + 1];
unsigned int memo[max_n + 1][0X40];
int n;

unsigned int patterns() {
	int i = 0;

	memo[0][0X0] = 1;
	while (i < n) {
		int length = 1;

		if (s[0][i] != s[1][i]) {
			length = 2;

			for (int used_mask = 0; used_mask < 0X40; used_mask++) {
				unsigned int x = memo[i][used_mask];

				if (x > 0) {
					for (int top = 0; top < 3; top++) {
						for (int bottom = 0; bottom < 3; bottom++) {
							if (top != bottom) {
								int selected_mask = ((1 << top) << 3) | (1 << bottom);

								if ((used_mask & selected_mask) == 0) {
									unsigned int &y = memo[i + length][selected_mask];

									y += x;
									y %= mod;
								}
							}
						}
					}
				}
			}
		}
		else {
			for (int used_mask = 0; used_mask < 0X40; used_mask++) {
				unsigned int x = memo[i][used_mask];

				if (x > 0) {
					for (int vertical = 0; vertical < 3; vertical++) {
						int selected_mask = ((1 << vertical) << 3) | (1 << vertical);

						if ((used_mask & selected_mask) == 0) {
							unsigned int &y = memo[i + length][selected_mask];

							y += x;
							y %= mod;
						}
					}
				}
			}
		}

		i += length;
	}

	unsigned int result = 0;
	for (int m = 0; m < 0X40; m++) {
		result += memo[n][m];
		result %= mod;
	}

	return result;
}

