const long long MOD = 1000000007;

int dp[60][4][4];

void solve(long long N, std::vector<std::string> S){
    S[0] = "$" + S[0];
    S[1] = "$" + S[1];
    dp[0][3][3] = 1;

    for(int i = 1; i <= N; ++i) {
        for(int j = 0; j < 3; ++j) for(int k = 0; k < 3; ++k) {
            if(S[0][i] == S[1][i]) {
                if (j != k) continue;
                for(int l = 0; l < 4; ++l) for(int m = 0; m < 4; ++m) {
                    if (l == j || m == k) continue;
                    dp[i][j][k] = (dp[i][j][k] + dp[i-1][l][m]) % MOD;
                }
            } else {
                if (j == k) continue;
                for(int l = 0; l < 4; ++l) for(int m = 0; m < 4; ++m) {
                    if (S[0][i-1] == S[0][i] && l != j) continue;
                    if (S[0][i-1] != S[0][i] && l == j) continue;
                    if (S[1][i-1] == S[1][i] && m != k) continue;
                    if (S[1][i-1] != S[1][i] && m == k) continue;
                    dp[i][j][k] = (dp[i][j][k] + dp[i-1][l][m]) %MOD;
                }
            }
        }
    }
    int res = 0;
    for(int i = 0; i < 3; ++i) for(int j = 0; j < 3; ++j) {
        res = (res + dp[N][i][j]) % MOD;
    }
    cout << res << endl;
}

