int n;

char S[2][60];
int dy[60][4][4];
const int MOD = 1000000007;

int go(int idx, int up, int down) {
	if (idx == n)return 1;

	auto& ret = dy[idx][up][down];
	if (ret != -1)return ret;
	ret = 0;

	if (S[0][idx] != S[1][idx]) {
		for (int u = 1; u <= 3; u++) {
			for (int d = 1; d <= 3; d++) {
				if (u != d && up!=u && down!=d) {
					ret += go(idx + 2, u, d);
					ret %= MOD;
				}
			}
		}
	}
	else {
		for (int p = 1; p <= 3; p++) {
			if (p != up && p != down) {
				ret += go(idx + 1, p, p);
				ret %= MOD;
			}
		}
	}
	return ret;

}


