// AC
/*
  Consider every "transition" := line cutting the rectangle. ie 
  A|BB
  A|CC

  There are 4 possible transitions. For each, calculate the number of ways to paint.

  Also, there are 2 way to start at the left most side. Count.

  The ans is the product of all those numbers mod 1e9+7. 
 */

#include <bits/stdc++.h>
using namespace std;

using tpl = tuple<char, int>;
typedef pair<int,int> pii;
