void fastStream(){cin.tie(0);std::ios_base::sync_with_stdio(0);}

const int mod = 1000000007;

int N;
char field[2][60];
int dp[2*60][4][4];



int rec(int pos, int uc, int dc){
    if(dp[pos][uc][dc] >= 0) 
        return dp[pos][uc][dc];
    ll res = 0;
    if(pos == N * 2){
        res = 1;
    }
    else{
        const int y = pos % 2;
        const int x = pos / 2;
        // 横に塗る場合
        if(x + 1 < N && field[y][x + 1] == field[y][x]){
            for(int i = 0; i < 3; i++){
                if(y == 0 && uc == i) continue;
                if(y == 1 && (dc == i || uc == i)) continue;
                if(y == 0) res = (res + rec(pos + 1, i, dc)) % mod;
                if(y == 1) res = (res + rec(pos + 1, uc, i)) % mod;
            }
        }
        // 縦に塗る場合
        else if(y + 1 < 2 && field[y + 1][x] == field[y][x]){
            for(int i = 0; i < 3; i++){
                if(uc == i || dc == i) continue;
                res = (res + rec(pos + 1, i, i)) % mod;
            }
        }
        // 塗らない場合
        else{
            res = (res + rec(pos + 1, uc, dc)) % mod;
        }
    }
    return dp[pos][uc][dc] = res;
}

int main(){
    cin >> N;
    for(int i = 0; i < 2; i++){
        for(int j = 0; j < N; j++){
            cin >> field[i][j];
        }
    }

    memset(dp, -1, sizeof(dp));
    // 左から順番に上、下、上、下と配置していく
    cout << rec(0, 3, 3) << endl;

    return 0;
}

