	for (int i = 1; i < format.size(); ++i){
		if (!format[i]){
			add(dp1[i][0][0], dp1[i - 1][1][2]);
			add(dp1[i][0][0], dp1[i - 1][2][1]);
			add(dp1[i][0][0], dp1[i - 1][1][1]);
			add(dp1[i][0][0], dp1[i - 1][2][2]);

			add(dp1[i][1][1], dp1[i - 1][0][2]);
			add(dp1[i][1][1], dp1[i - 1][2][0]);
			add(dp1[i][1][1], dp1[i - 1][0][0]);
			add(dp1[i][1][1], dp1[i - 1][2][2]);

			add(dp1[i][2][2], dp1[i - 1][1][0]);
			add(dp1[i][2][2], dp1[i - 1][0][1]);
			add(dp1[i][2][2], dp1[i - 1][1][1]);
			add(dp1[i][2][2], dp1[i - 1][0][0]);
		}
		else{

			for (int j = 0; j < MAXN; ++j){
				dp2[j][0][1] = 0;
				dp2[j][0][2] = 0;
				dp2[j][1][0] = 0;
				dp2[j][1][2] = 0;
				dp2[j][2][0] = 0;
				dp2[j][2][1] = 0;
			}

			add(dp2[1][0][1], dp1[i - 1][2][2]);
			add(dp2[1][0][2], dp1[i - 1][1][1]);
			add(dp2[1][1][0], dp1[i - 1][2][2]);
			add(dp2[1][2][0], dp1[i - 1][1][1]);
			add(dp2[1][1][2], dp1[i - 1][0][0]);
			add(dp2[1][2][1], dp1[i - 1][0][0]);

			for (int j = 2; j < MAXN; ++j){
				add(dp2[j][0][1], dp2[j - 1][1][0]);
				add(dp2[j][0][1], dp2[j - 1][1][2]);
				add(dp2[j][0][1], dp2[j - 1][2][0]);

				add(dp2[j][0][2], dp2[j - 1][1][0]);
				add(dp2[j][0][2], dp2[j - 1][2][0]);
				add(dp2[j][0][2], dp2[j - 1][2][1]);

				add(dp2[j][1][0], dp2[j - 1][0][1]);
				add(dp2[j][1][0], dp2[j - 1][2][1]);
				add(dp2[j][1][0], dp2[j - 1][0][2]);

				add(dp2[j][2][0], dp2[j - 1][0][1]);
				add(dp2[j][2][0], dp2[j - 1][1][2]);
				add(dp2[j][2][0], dp2[j - 1][0][2]);

				add(dp2[j][1][2], dp2[j - 1][0][1]);
				add(dp2[j][1][2], dp2[j - 1][2][1]);
				add(dp2[j][1][2], dp2[j - 1][2][0]);

				add(dp2[j][2][1], dp2[j - 1][1][0]);
				add(dp2[j][2][1], dp2[j - 1][1][2]);
				add(dp2[j][2][1], dp2[j - 1][0][2]);
			}

			dp1[i][0][1] = dp2[format[i]][0][1];
			dp1[i][1][0] = dp2[format[i]][0][1];
			dp1[i][0][2] = dp2[format[i]][0][1];
			dp1[i][2][0] = dp2[format[i]][0][1];
			dp1[i][1][2] = dp2[format[i]][0][1];
			dp1[i][2][1] = dp2[format[i]][0][1];
		}

	}

	int ans = 0;
	int l = format.size() - 1;
	add(ans, dp1[l][0][0]);
	add(ans, dp1[l][1][1]);
	add(ans, dp1[l][2][2]);
	add(ans, dp1[l][0][1]);
	add(ans, dp1[l][1][0]);
	add(ans, dp1[l][0][2]);
	add(ans, dp1[l][2][0]);
	add(ans, dp1[l][1][2]);
	add(ans, dp1[l][2][1]);

	cout << ans;
	return 0;
}

