namespace NyaGadget
{
	/*** ランレングス圧縮ライブラリ ***/

	template <class T> struct RunLengthEncodingResult
	{	// ランレングス圧縮の結果を格納する構造体
		long long begin = 0; // 区間開始位置
		long long end = 0;   // 区間終了位置
		std::vector<T> sub;  // 区間データ
	};

	template <> struct RunLengthEncodingResult<std::string>
	{	// ランレングス圧縮の結果を格納する構造体
		long long begin = 0; // 区間開始位置
		long long end = 0;   // 区間終了位置
		std::string sub;     // 区間データ
	};

	template <class T> struct DS_NyaaRLE
	{
		std::vector<RunLengthEncodingResult<T>> res;

		/**
		@brief 文字列のランレングス圧縮
		@param s 圧縮する文字列
		@param res 圧縮結果
		**/
		decltype(res)& Run(std::string& s)
		{
			res.push_back({ 0, 0, "" });
			for (long long i = 0; i < (long long)s.size(); i++)
			{
				if (i == (long long)s.size() - 1)
				{
					res.back().end = i + 1;
					res.back().sub = s.substr(res.back().begin, i + 1 - res.back().begin);
					return res;
				}
				if (s[i] != s[i + 1])
				{
					res.back().end = i + 1;
					res.back().sub = s.substr(res.back().begin, i + 1 - res.back().begin);
					res.push_back({ i + 1, 0, "" });
				}
			}
			return res;
		}

		/**
		@brief 配列のランレングス圧縮
		@param v 圧縮する配列
		@param res 圧縮結果
		**/
		decltype(res)& Run(std::vector<T>& v)
		{
			res.push_back({ 0, 0, std::vector<T>() });
			for (long long i = 0; i < (long long)v.size(); i++)
			{
				if (i == (long long)v.size() - 1)
				{
					res.back().end = i + 1;
					for (long long j = res.back().begin; j < i + 1; j++) res.back().sub.push_back(v[j]);
					return res;
				}
				if (!IsSame(v[i], v[i + 1]))
				{
					res.back().end = i + 1;
					for (long long j = res.back().begin; j < i + 1; j++) res.back().sub.push_back(v[j]);
					res.push_back({ i + 1, 0, std::vector<T>() });
				}
			}
			return res;
		}

		bool IsSame(T& l, T& r)
		{	// lとrが同値かどうか調べる
			return l == r;
		}
	};
}

namespace NyaGadget
{
	/***** MOD 関数ライブラリ *****/

	struct NT_Mod
	{
		static long long Add(long long x, long long y, long long mod)
		{
			x = (x + y) % mod;
			if (x >= mod) x -= mod;
			return x;
		}

		static long long Sub(long long x, long long y, long long mod)
		{
			x = (x - y) % mod;
			if (x < 0) x += mod;
			return x;
		}

		static long long Mul(long long x, long long y, long long mod)
		{
			x = (unsigned long long) x * y % mod;
			return x;
		}

		static long long Div(long long x, long long y, long long mod)
		{
			x = x * Inv(y, mod) % mod;
			return x;
		}

		static long long Pow(long long x, long long n, long long mod)
		{
			long long res = 1;
			if (0 < n)
			{
				res = Pow(x, n / 2, mod);
				res = Mul(res, res, mod);
				if (n % 2 != 0) res = Mul(res, x, mod);
			}
			return res;
		}

		static long long Inv(long long a, long long mod)
		{
			long long b = mod, u = 1, v = 0;
			while (b)
			{
				long long t = a / b;
				a -= t * b; std::swap(a, b);
				u -= t * v; std::swap(u, v);
			}
			u %= mod;
			return (u < 0) ? u + mod : u;
		}
	};

	/***** MOD 型ライブラリ *****/

	template<long long mod> struct NT_ModLL
	{	// 非型テンプレートパラメータ
		long long x;

		// コンストラクタ
		NT_ModLL() { x = 0; }
		NT_ModLL(long long x_)
		{
			x = x_ % mod + mod;
			if (x >= mod) x -= mod;
		}

		// 符号
		NT_ModLL operator + () const { return x; }
		NT_ModLL operator - () const { return (-x < 0) ? mod - x : -x; }

		// 加減乗除
		NT_ModLL operator + (NT_ModLL r) const { return NT_ModLL(*this) += r; }
		NT_ModLL operator - (NT_ModLL r) const { return NT_ModLL(*this) -= r; }
		NT_ModLL operator * (NT_ModLL r) const { return NT_ModLL(*this) *= r; }
		NT_ModLL operator / (NT_ModLL r) const { return NT_ModLL(*this) /= r; }
		NT_ModLL& operator += (NT_ModLL r)
		{	// 加算代入
			if ((x += r.x) >= mod) x -= mod;
			return *this;
		}
		NT_ModLL& operator -= (NT_ModLL r)
		{	// 減算代入
			if ((x -= r.x) < 0) x += mod;
			return *this;
		}
		NT_ModLL& operator *= (NT_ModLL r)
		{	//乗算代入
			x = (unsigned long long) x * r.x % mod;
			return *this;
		}
		NT_ModLL& operator /= (NT_ModLL r)
		{	// 除算代入
			x = x * Inv(r.x, mod) % mod;
			return *this;
		}

		long long Inv(long long a, long long m)
		{	// 逆元 x^{-1} (主に除算演算子で使用)
			long long b = m, u = 1, v = 0;
			while (b)
			{
				long long t = a / b;
				a -= t * b; swap(a, b);
				u -= t * v; swap(u, v);
			}
			u %= m;
			return (u < 0) ? u + m : u;
		}

		// 比較
		bool operator == (NT_ModLL& r) const { return x == r.x; }
		bool operator != (NT_ModLL& r) const { return x != r.x; }
		bool operator <  (NT_ModLL& r) const { return x < r.x; }
		bool operator <= (NT_ModLL& r) const { return x <= r.x; }
		bool operator >  (NT_ModLL& r) const { return x > r.x; }
		bool operator >= (NT_ModLL& r) const { return x >= r.x; }

		// 入出力
		friend ostream& operator << (ostream& s, NT_ModLL<mod> a)
		{
			s << a.x, a.x %= mod;
			return s;
		}
		friend istream& operator >> (istream& s, NT_ModLL<mod>& a)
		{
			s >> a.x, a.x %= mod;
			return s;
		}

		NT_ModLL Pow(long long x, long long n)
		{	// 累乗(繰り返し二乗法)、計算量O(logN)
			NT_ModLL res = 1;
			if (0 < n)
			{
				res = Pow(x, n / 2);
				res = res * res;
				if (n % 2 != 0) res *= x;
			}
			return res;
		}
	};
}



