					if (c == c1 || c == c4) continue;
					for (int c3=1; c3 <= 3; c3++)
						dp[i][0][c][c1][c] = (dp[i][0][c][c1][c] + dp[i-1][c1][0][c3][c4]) % MOD;
				}
		}
	}
	ll res = 0;
	for (int c1=1; c1<=3; c1++)
	for (int c2=1; c2<=3; c2++)
	for (int c3=1; c3<=3; c3++)
	for (int c4=1; c4<=3; c4++)
		res = (res + dp[n-1][c1][c2][c3][c4]) % MOD;
	cout << res << "\n";
}

