            else {
                if(a[i] == b[i]) { // 当前位置是 X
                    if(p == 1) sum = (sum * 2) % MOD; // 如果上一个位置是 X，即 X -> X 
                    else sum = (sum * 1) % MOD; // 如果上一个位置是 Y，即 Y -> X 
                    i ++;
                    p = 1;
                }
                else { // 当前位置是 Y
                    if(p == 1) sum = (sum * 2) % MOD; // 如果上一个位置是 X，即 X -> Y 
                    else sum = (sum * 3) % MOD; // 如果上一个位置是 Y，即 Y -> Y
                    i += 2;
                    p = 2;
                }
            }
        }
