  int n = ri();
  auto s1 = rs(), s2 = rs();

  vvvm dp(n+1, vvm(4, vm(4)));

  dp[0][0][0] = 1;

  rep(i, n) rep(a, 4) rep(b, 4) if (dp[i][a][b].x) {
    if (s1[i] == s2[i]) {
      rep(c, 1, 4) {
        if (a != c && b != c) {
          dp[i+1][c][c] += dp[i][a][b];
        }
      }
    }
    else {
      rep(c, 1, 4) rep(d, 1, 4) if (c != d) {
        if (a != c && b != d) {
          dp[i+2][c][d] += dp[i][a][b];
        }
      }
    }
  }

  out(dp);

  mint ans;
  rep(c, 1, 4) rep(d, 1, 4) {
    ans += dp[n][c][d];
  }
