            if(e != corA && e != corB){
                ans += solve(cur + 1, e, e);
                ans %= mod;
            }
        }
    } else {
        for(int e = 1; e <= 3; e++){
            for(int f = 1; f <= 3; f++){
                if(e != f && corA != e && corB != f){
                    ans += solve(cur + 2, e, f);
                    ans %= mod;
                }
            }
        }
