void add_to_kanren(char* kanren, const char c)
{
	for(int i=0; i<MAX_KANREN; i++){
		if(kanren[i] == c){ //既に関連付け
			return;
		}
		if(kanren[i] == '\0'){
			kanren[i] = c;
			return;
		}
	}
}

enum{
	COLOR_R = 1,
	COLOR_G,
	COLOR_B,
	COLOR_MAX,
};

#define TRUE 1
#define FALSE 0

int check(char* kanren, int *color_for_each, int index)
{
	for(int i=0;i<MAX_KANREN;i++){
		if(kanren[i]-'A' == index) continue; //自分
		if(color_for_each[kanren[i]-'A'] == 0) return TRUE;
		if(color_for_each[kanren[i]-'A'] == color_for_each[index]){
			return FALSE;
		}
	}
	return TRUE;
}

int tryit(char* kanren, int *color_for_each, int index, int *ans)
{
	if(index==58){
		*ans = *ans+1;
		return TRUE;
	}

	for(int color=COLOR_R;color<COLOR_MAX;color++){
		if(kanren[index*MAX_KANREN]== '\0'){ //使われてないドミノ
			if(tryit(kanren, color_for_each, index+1, ans)==TRUE){
				return TRUE;
			}else return FALSE;
		}else{
			color_for_each[index] = color;
			if(check(&kanren[index*MAX_KANREN], color_for_each, index)==TRUE){
				tryit(kanren, color_for_each, index+1, ans);
			}
			color_for_each[index] = 0;
		}
	}

	return TRUE;
}


int main(void){
	int N;
	char S[2][52];
	char kanren[52+6][MAX_KANREN]; //+6はZとaの間に6文字があるため
	int color_for_each[52+6]; //再帰用  
	int ans = 0;
	int sou = 0;

	memset(kanren, '\0', sizeof(kanren));
	memset(color_for_each, 0, sizeof(color_for_each));

	scanf("%d", &N);

	for(int i=0;i<2;i++){
		scanf("%s", S[i]);
	}
	for(int ii=0;ii<2;ii++){
		for(int jj=0;jj<N;jj++){
			//関連をつけよう
			if(GETU!=0){
				add_to_kanren(&kanren[GETS - 'A'][0], GETU);
			}
			if(GETL!=0){
				add_to_kanren(&kanren[GETS - 'A'][0], GETL);
			}
			if(GETD!=0){
				add_to_kanren(&kanren[GETS - 'A'][0], GETD);
			}
