template <class T, class T2> long long modpower(long long radix, T x, T2 mod) {
    // 高速階乗計算 radix^x
    long long ans = 1;
    auto moder    = [&]() {
        if (mod != 0)
            ans %= mod;
    };
    while (0 < x) {
        if (x & 1) {
            ans = ans * radix;
            moder();
        }
        radix = radix * radix;
        moder();
        x >>= 1;
    }
    return ans == 0 ? 1 : ans;
}

