			auto use = popEnd(next);
			backUp = ~use;
			backDn = ~use;
		}
		else
		{
			if (backUp == backDn)
			{
				ret *= backUp.count() * (backUp.count() - 1ll);
				ret %= MOD;
				auto useUp = popEnd(backUp);
				auto useDn = popEnd(backDn & ~useUp);
				backUp = ~useUp;
				backDn = ~useDn;
			}
			else
			{
				ret *= 3;
				ret %= MOD;
			}
			i++;
		}
