void solve() {
  long N;
  string S1, S2;
  cin >> N >> S1 >> S2;

  unordered_map<string, long> state;
  if (S1[0] == S2[0]) {
    state["aa"] = 1;
    state["bb"] = 1;
    state["cc"] = 1;
  } else {
    state["ab"] = 1;
    state["ac"] = 1;
    state["ba"] = 1;
    state["bc"] = 1;
    state["ca"] = 1;
    state["cb"] = 1;
  }

  for (long i = 1; i < N; i++) {
    if (S1[i-1] == S1[i]) continue;
    unordered_map<string, long> next_state;
    if (S1[i-1] == S2[i-1]) {
      if (S1[i] == S2[i]) {
        next_state["aa"] = state["bb"] + state["cc"];
        next_state["bb"] = state["aa"] + state["cc"];
        next_state["cc"] = state["aa"] + state["bb"];
      } else {
        next_state["ab"] = state["cc"];
        next_state["ac"] = state["bb"];
        next_state["ba"] = state["cc"];
        next_state["bc"] = state["aa"];
        next_state["ca"] = state["bb"];
        next_state["cb"] = state["aa"];
      }
    } else {
      if (S1[i] == S2[i]) {
        next_state["aa"] = state["bc"] + state["cb"];
        next_state["bb"] = state["ac"] + state["ca"];
        next_state["cc"] = state["ab"] + state["ba"];
      } else {
        next_state["ab"] = state["ba"] + state["bc"] + state["ca"];
        next_state["ac"] = state["ba"] + state["ca"] + state["cb"];
        next_state["ba"] = state["ab"] + state["ac"] + state["cb"];
        next_state["bc"] = state["ab"] + state["ca"] + state["cb"];
        next_state["ca"] = state["ab"] + state["ac"] + state["bc"];
        next_state["cb"] = state["ac"] + state["ba"] + state["bc"];
      }
    }
    for (auto it: next_state) next_state[it.first] %= MOD;
    state = next_state;
  }

  long ans = 0;
  for (auto it: state) ans += it.second;
  ans %= MOD;
  cout << ans << endl;
}

