				dp[i] %= MOD;
			}
			else {
				dp[i] = dp[i - 2] * 1;
				dp[i] %= MOD;
			}
		}
		else {
			if (flag[i - 1]) {
				dp[i] = dp[i - 1] * 2;
				dp[i] %= MOD;
				dp[i + 1] = dp[i];
				i++;
			}
