ll power(ll base,int p){
  if(!p)return 1;
  ll ret=power(base,p/2);
  ret*=ret;
  ret%=mod;
  if(p&1)ret*=base,ret%=mod;
  return ret;
}
ll modInverse(int a){
  return power(a,mod-2);
}

