ll solve(int a,int b,int idx){
  if(idx>n)return 0;
  if(idx==n)return 1;
  if(dp[a][b][idx]!=-1)return dp[a][b][idx];
  ll ret=0;
  if(s1[idx]==s2[idx]){
     for(int i=0;i<3;i++){
        if(i==a||i==b)continue;
        ret+=solve(i,i,idx+1);
        ret%=mod;
     }
  }
  else{
    for(int i=0;i<3;i++){
        for(int j=0;j<3;j++){
            if(i==j||i==a||j==b)continue;
            ret+=solve(i,j,idx+2);
            ret%=mod;
        }
    }
  }
  return dp[a][b][idx]=ret;
}
