int rec(int idx, int a, int b)
{
  if(idx == N) return (1);
  if(~dp[idx][a][b]) return (dp[idx][a][b]);
  int64 ret = 0;
  if(A[0][idx] == A[1][idx]) {
    for(int i = 1; i <= 3; i++) {
      if(a != i && b != i) ret += rec(idx + 1, i, i);
    }
  } else {
    for(int i = 1; i <= 3; i++) {
      for(int j = 1; j <= 3; j++) {
        if(i != j && a != i && b != j) {
          ret += rec(idx + 2, i, j);
        }
      }
    }
  }
  return (dp[idx][a][b] = ret % mod);
}

