        }
        scanf("\n");
    }
    for ( int msk = 0; msk <= 7; msk++ ){
        for ( int fl = 0; fl <= 1; fl++ ){
            f[n+1][msk][fl] = 1;
        }
    }
    for ( int i = n; i >= 1; i-- ){
        for ( int msk = 0; msk <= 7; msk++ ){
            for ( int fl = 0; fl <= 1; fl++ ){

                if ( a[1][i] == a[2][i] ){
                    for ( int clr = 0; clr <= 2; clr++ ){
                        int bit = ( msk >> clr ) & 1;
                        if ( !bit ){
                            f[i][msk][fl] = ( f[i][msk][fl] + f[i+1][ ( 1 << clr ) ][fl] ) % mod;
                        }
                    }
                }
                else{
                    int cntBits = getCnt(msk);
                    if ( cntBits < 2 ){
                        for ( int clr1 = 0; clr1 <= 2; clr1++ ){
                            for ( int clr2 = 0; clr2 <= 2; clr2++ ){
                                if ( clr1 == clr2 ){
                                    continue;
                                }
                                if ( ( 1 << clr1 ) + ( 1 << clr2 ) + msk == 7 ){
                                    int nxtMsk, nxtfl = 0;
                                    nxtMsk = ( 1 << clr1 ) + ( 1 << clr2 );
                                    if ( clr1 < clr2 ){
                                        nxtfl = 1;
                                    }
                                    f[i][msk][fl] = ( f[i][msk][fl] + f[i+2][nxtMsk][nxtfl] ) % mod;
                                }
                            }
                        }
                        continue;
                    }
                    int upClr = -1, downClr = -1;
                    for ( int clr = 0; clr <= 2; clr++ ){
                        if ( upClr == -1 ){
                            upClr = clr;
                        }
                        else{
                            downClr = clr;
                        }
                    }
                    if ( fl ){
                        swap( upClr, downClr );
                    }
                    for ( int clr1 = 0; clr1 <= 2; clr1++ ){
                        for ( int clr2 = 0; clr2 <= 2; clr2++ ){
                            if ( clr1 == clr2 ){
                                continue;
                            }
                            if ( clr1 != upClr && clr2 != downClr ){

                                int nxtMsk, nxtfl = 0;
                                nxtMsk = ( 1 << clr1 ) + ( 1 << clr2 );
                                if ( clr1 < clr2 ){
                                    nxtfl = 1;
                                }
                                f[i][msk][fl] = ( f[i][msk][fl] + f[i+2][nxtMsk][nxtfl] ) % mod;
                            }
                        }
                    }
                }
            }
        }
    }
    int ans = 0;
    if ( a[1][1] == a[2][1] ){
        for ( int j = 0; j <= 2; j++ ){
            ans = ( ans + f[2][ ( 1 << j ) ][0] ) % mod;
        }
    }
    else{
        for ( int i = 0; i <= 2; i++ ){
            for ( int j = 0; j <= 2; j++ ){
