            out << 6 << '\n';
            return;
        }
        ll ans = 0;
        int pos = 0;
        bool tate = true;
        if (S[0][0] == S[1][0]) {
            ans += 3;
            pos += 1;
            tate = true;
        }
        else if (S[0][0] == S[0][1]) {
            ans += 6;
            pos += 2;
            tate = false;
        }
        reu(i, pos, N) {
            if (tate) {
                if (S[0][i] == S[1][i]) {
                    ans = (ans * 2) % MOD;
                    tate = true;
                }
                else if (i + 1 < N && S[0][i] == S[0][i + 1]) {
                    ans = (ans * 2) % MOD;
                    i++;
                    tate = false;
                }
            }
            else {
                if (S[0][i] == S[1][i]) {
                    ans = (ans * 1) % MOD;
                    tate = true;
                }
                else if (i + 1 < N && S[0][i] == S[0][i + 1]) {
                    ans = (ans * 3) % MOD;
                    i++;
                    tate = false;
                }
            }
        }
        out << ans << '\n';
    }
};
