	scanf("%s", t);
	memset(dp, 0, sizeof(dp));
	if(s[0] == t[0]){
		dp[0][0][0] = dp[0][1][1] = dp[0][2][2] = 1;
	} else {
		dp[0][0][1] = dp[0][1][0] = 1;
		dp[0][0][2] = dp[0][2][0] = 1;
		dp[0][1][2] = dp[0][2][1] = 1;
	}
	for(int i=1; i<n; i++){
		for(int j=0; j<3; j++){
			for(int k=0; k<3; k++){
				if(j == k){
					if(s[i] == t[i]){
						for(int l=0; l<3; l++){
							if(l == j)	continue;
							dp[i][l][l] = (dp[i][l][l] + dp[i-1][j][k]) % mod;
						}
					} else {
						for(int l=0; l<3; l++){
							if(l == j)	continue;
							dp[i][l][3 - j - l] = (dp[i][l][3-j-l] + dp[i-1][j][k]) % mod;
						}
					}
				} else {
					if(s[i] == t[i]){
						int l = 3 - j - k;
						dp[i][l][l] = (dp[i][l][l] + dp[i-1][j][k]) % mod;
					} else {
						for(int l=0; l<3; l++){
							if(s[i]!=s[i-1] && l == j)	continue;
							if(s[i]==s[i-1] && l != j)	continue;
							for(int m=0; m<3; m++){
								if(m==l)	continue;
								if(t[i]!=t[i-1] && m==k)	continue;
								if(t[i]==t[i-1] && m!=k)	continue;
								dp[i][l][m] = (dp[i][l][m] + dp[i-1][j][k])% mod;
							}
						}
					}
				}
			}
		}
	}
	LL ans = 0;
	for(int i=0; i<3; i++){
		for(int j=0; j<3; j++)	ans += dp[n-1][i][j];
	}
	printf("%lld\n", ans % mod);
	return 0;
}

