ll dpfun(int i, int last, int color, int c1, int c2)
{
        if(i >= n) return 1;

        if(dp[i][last][color] != -1) return dp[i][last][color];

        ll ret = 0;

        if(!last){
                if(arr[i] == 2){
                        FOR(j, 1, 3){
                                FOR(k, 1, 3){
                                        if(j == k) continue;
                                        ret = (ret + dpfun(i + 1, 2, j + k, j, k)) % mod;
                                }
                        }
                }
                else{
                        FOR(j, 1, 3) ret = (ret + dpfun(i + 1, 1, j, 0, 0)) % mod;
                }
        }
        else if(last == 1){
                if(arr[i] == 1){
                        FOR(j, 1, 3){
                                if(j != color)
                                        ret = (ret + dpfun(i + 1, 1, j, 0, 0)) % mod;
                        }
                }
                else{
                       FOR(j, 1, 3){
                                FOR(k, 1, 3){
                                        if(j == k || j == color || k == color) continue;
                                        ret = (ret + dpfun(i + 1, 2, j + k, j, k)) % mod;
                                }
                        }
                }
        }
        else{
                if(arr[i] == 1){
                        ret = (ret + dpfun(i + 1, 1, 6 - color, 0, 0)) % mod;
                }
                else{
                       FOR(j, 1, 3){
                                FOR(k, 1, 3){
                                        if(j == k || (j == c1) || (k == c2)) continue;
                                        ret = (ret + dpfun(i + 1, 2, j + k, j, k)) % mod;
                                }
                        }
                }
        }

        return dp[i][last][color] = ret;
}

