typedef lib::modnum<1000000007> mod_t;

boost::optional<int> initialize(
	std::vector<std::set<int>> const& edge,
	std::vector<boost::optional<int>>& color,
	std::set<int>& start,
	int now, int prev, int N, int depth)
{
	for (auto const& e : edge[now])
	{
		if (e == prev)
		{
			continue;
		}
		if (e == N - 1)
		{
			color[now] = 2 * depth > depth + 1;
			start.emplace(now);
			return depth + 1;
		}
		if (auto result = initialize(edge, color, start, e, now, N, depth + 1))
		{
			color[now] = 2 * depth > *result;
			start.emplace(now);
			return result;
		}
	}
	return boost::none;
}

void coloring(std::vector<std::set<int>>const& edge, std::vector<boost::optional<int>>& color, int now, int prev, int c)
{
	color[now] = c;
	for (auto const& e : edge[now])
	{
		if (e == prev)
		{
			continue;
		}
		if (color[e])
		{
			continue;
		}
		coloring(edge, color, e, now, c);
	}
}

