struct modint {
  int n;
  modint(int n = 0) : n(n) {}
};

modint operator+(modint a, modint b) { return modint((a.n += b.n) >= mod ? a.n - mod : a.n); }
modint operator-(modint a, modint b) { return modint((a.n -= b.n) < 0 ? a.n + mod : a.n); }
modint operator*(modint a, modint b) { return modint(1LL * a.n * b.n % mod); }
modint &operator+=(modint &a, modint b) { return a = a + b; }
modint &operator-=(modint &a, modint b) { return a = a - b; }
modint &operator*=(modint &a, modint b) { return a = a * b; }

modint dp[60][3][3];

int main() {
  int n;
  cin >> n;

  string a[2];
  cin >> a[0] >> a[1];

  if (a[0][0] == a[1][0]) {
    for (int i = 0; i < 3; i++) {
      dp[0][i][i] = 1;
    }
  } else {
    for (int i = 0; i < 3; i++) {
      for (int j = 0; j < 3; j++) {
        dp[0][i][j] = i != j;
      }
    }
  }

  for (int i = 1; i < n; i++) {
    if (a[0][i] == a[1][i]) {
      for (int j = 0; j < 3; j++) {
        for (int k = 0; k < 3; k++) {
          for (int l = 0; l < 3; l++) {
            if (l == j || l == k) continue;
            dp[i][l][l] += dp[i - 1][j][k];
          }
        }
      }
    } else if (a[0][i] == a[0][i - 1]) {
      for (int j = 0; j < 3; j++) {
        for (int k = 0; k < 3; k++) {
          dp[i][j][k] += dp[i - 1][j][k];
        }
      }
    } else {
      for (int j = 0; j < 3; j++) {
        for (int k = 0; k < 3; k++) {
          for (int l = 0; l < 3; l++) {
            for (int m = 0; m < 3; m++) {
              if (j == l || k == m || l == m) continue;
              dp[i][l][m] += dp[i - 1][j][k];
            }
          }
        }
      }
    }
  }

  modint ans = 0;
  for (int i = 0; i < 3; i++) {
    for (int j = 0; j < 3; j++) {
      ans += dp[n - 1][i][j];
    }
  }
  cout << ans.n << endl;
}

