    dp[0][0][1] = dp[0][0][2] = dp[0][1][2] =
    dp[0][1][0] = dp[0][2][0] = dp[0][2][1] =
    dp[1][0][1] = dp[1][0][2] = dp[1][1][2] =
    dp[1][1][0] = dp[1][2][0] = dp[1][2][1] = 1;
