					tot += 3;
					prev = 1;
				}
			} else {
				if (i + 1 < n) {
					if (prev == -1) {
						if (g[0][i] == g[0][i+1]) {
							i++;
							tot *= 3;
						} else {
							tot *= 1;
							prev = 1;
						}
					} else {
						if (g[0][i] == g[0][i+1]) {
							i++;
							tot *= 2;
							prev = -1;
						} else {
							tot *= 2;
						}
					}
				} else {
					if (prev == -1) tot *= 1;
					else tot *= 3;
				}
			}
			tot %= MOD;
		}
		cout << tot << endl;
	}
}

