#include<bits/stdc++.h>
#define N 60
#define MOD 1000000007
using namespace std;

int n,dp[N][5][5];
char s[2][N];

int dfs(int now,int bust,int balt) {

  int salt=-1,sust=-1;
  int ret=0;
  if(now>n) return 1;
  if(~dp[now][bust][balt]) return dp[now][bust][balt];
  if(s[0][now]==s[0][now-1]) sust=bust;
  if(s[1][now]==s[1][now-1]) salt=balt;
  if(s[0][now]!=s[1][now] && ~salt && ~sust && salt==sust) return dp[now][bust][balt]=0;
  for(int i=0;i<3;i++) {
    for(int j=0;j<3;j++) {
      if((~salt && i!=salt) || (~sust && j!=sust)) continue ;
      if(s[0][now]==s[1][now] && i!=j) continue ;
      if(s[0][now]!=s[1][now] && i==j) continue ;
      if(s[0][now-1]!=s[0][now] && bust==i) continue ;
      if(s[1][now-1]!=s[1][now] && balt==j) continue ;
      ret=(ret+dfs(now+1,i,j))%MOD;
    }
  }
  return dp[now][bust][balt]=ret;

}

