const int CLR = 3;
const int MOD = 1e9 + 7;

int dp[CLR][CLR][N];

void add(int& a, int b) {
	a += b;
	if (a >= MOD)
		a -= MOD;
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);
	int n;
	cin >> n;
	cin >> s[0] >> s[1];
	if (s[0][0] == s[1][0]) {
		for (int i = 0; i < CLR; ++i) {
			dp[i][i][0] = 1;
		}
	} else {
		for (int i = 0; i < CLR; ++i) {
			for (int j = 0; j < CLR; ++j) {
				dp[i][j][0] = i != j;
			}
		}
	}
	for (int i = 0; i + 1 < n; ++i) {
		for (int u = 0; u < CLR; ++u) {
			for (int v = 0; v < CLR; ++v) {
				if (dp[u][v][i])
					for (int a = 0; a < CLR; ++a) {
						if (s[0][i] == s[0][i + 1] && a != u)
							continue;
						if (s[0][i] != s[0][i + 1] && a == u)
							continue;							
						for (int b = 0; b < CLR; ++b) {
							if (s[1][i] == s[1][i + 1] && b != v)
								continue;
							if (s[1][i] != s[1][i + 1] && b == v)
								continue;

							if (s[0][i + 1] == s[1][i + 1]) {
								if (a == b) {
									add(dp[a][b][i + 1], dp[u][v][i]);
								}								
							} else {
								if (a != b) {
									add(dp[a][b][i + 1], dp[u][v][i]);
								}
							}				
						}
					}
			}
		}
	}
	int total = 0;
	for (int i = 0; i < CLR; ++i) 
		for (int j = 0; j < CLR; ++j)
			add(total, dp[i][j][n - 1]);
	cout << total << endl;

	return 0;
}

