ll solve(int i, int prev1, int prev2) 
{
    ll ret = 0;
    if (board1[i] == board2[i]) {
        //pr("case 1") nl
        for (int c=0; c<3; c++) {
            if (c != prev1 && c != prev2) {
                ret = (ret + dp[i+1][c][c]) % MOD;
            }
        }
    }
    else {
        //2 different colours
        //pr("case 2") nl
        for (int c1=0; c1<3; c1++) {
            for (int c2=0; c2<3; c2++) {
                if (c1 != prev1 && c2 != prev2 && c1 != c2) {
                    ret = (ret + dp[i+1][c1][c2]) % MOD;
                }
            }
        }
    }
    return ret;
}

