                        if (prev_type == '_') {
                                ans *= 3LL;
                                ans %= mod;
                        }
                        if (prev_type == 's') {
                                ans *= 2LL;
                                ans %= mod;
                        }
                        if (prev_type == 'd') {
                                ans *= 1LL;
                        }
                        prev_type = 's';
                }
                else {
                        if (prev_type == '_') {
                                ans *= 6LL;
                                ans %= mod;
                        }
                        if (prev_type == 's') {
                                ans *= 2LL;
                                ans %= mod;
                        }
                        if (prev_type == 'd') {
                                ans *= 3LL;
                                ans %= mod;
                        }
                        prev_type = 'd';
                        ++i;
                }
        }

        cout << ans;

        return 0;
}

