#define MOD 1000000007

ll dp[100][2];

int main() {
  clr(dp,0);
  ll n;
  cin>>n;
  string s1,s2;
  cin>>s1;
  cin>>s2;
  s1 += "+";
  s2 += "-";
  if(n==1){
    cout << 3 << endl;
    return 0;
  }
  if(s1[0]==s2[0]){
    dp[0][0] = 3;
  }
  else{
    dp[1][1] = 6;
  }
  rep(i,1,n){
    if(s1[i]==s2[i]){
      dp[i][0] += dp[i-1][0]*2;
      dp[i][0] += dp[i-1][1];
      dp[i][0] %= MOD;
    }
    else if(s1[i]==s1[i+1]){
      dp[i+1][1] += dp[i-1][0]*2;
      dp[i+1][1] += dp[i-1][1]*3;
      dp[i+1][1] %= MOD;
    }
  }
  ll ans = dp[n-1][0] + dp[n-1][1];
  ans %= MOD;
  cout << ans << endl;
  return 0;
}

