int f(int np, char *A) {
	unsigned int ans;
	if (A[0] == 't') ans = 3;
	else ans = 6;
	for (int i = 1; i < np; i++) {
		if (A[i] == 't') {
			if (A[i-1] == 't') ans *= 2;
			else ;
		} else {
			if (A[i-1] == 't') ans *= 2;
			else ans *= 3;
		}
		ans %= 1000000007;
	}
	return ans;
}

