		if (map[0][0] == map[1][0]) {
			answer = 3;
			i = 1;
		}
		// Placed horizontally
		else {
			answer = 6;
			i = 2;
		}

		for (; i < N; i++) {
			// Placed vertically
			if (map[0][i] == map[1][i]) {
				// Previous domino placed vertically
				if (map[0][i - 1] == map[1][i - 1]) {
					answer *= 2;
				}
				// Previous domino placed horizontally
				else {
					answer *= 1;
				}
			}
			// Placed horizontally
			else {
				// Previous domino placed vertically
				if (map[0][i - 1] == map[1][i - 1]) {
					answer *= 2;
				}
				// Previous domino placed horizontally
				else {
					answer *= 3;
				}
				i++;
			}
			answer %= MOD;
		}

		System.out.println(answer);
	}
