            } else if (ans.charAt(i - 1) == 'y' && ans.charAt(i) == 'x') {
                res *= 1;
            } else if (ans.charAt(i - 1) == 'y' && ans.charAt(i) == 'y') {
                res *= 3;
            }
            res %= MOD;
        }
        System.out.println(res);
    }
}

