	public static long domino(String S1) {
		long score = 1;
		boolean hor = false;

		int i = 0;
		if(S1.charAt(0) == S1.charAt(1) ) {
			score *= 6;
			hor = true;
			i = 2;
		}else {
			score *= 3;
			hor = false;
			i = 1;
		}

		for(; i < S1.length()-1; i++) {
			if(S1.charAt(i) == S1.charAt(i+1)) {
				if(hor) {
					score *= 3;
				}else {
					score *= 2;
				}
				hor = true;
				i++;
			}else {
				if(!hor) {
					score *=2;
				}
				hor = false;
			}
		}

		if(!hor && i == S1.length()-1) score *= 2;

		return score;
	}

