import java.io.InputStream;
import java.io.IOException;
import java.io.PrintStream;
import java.util.*;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class Main {

  public static void main(String[] args) {
    solve(System.in, System.out);
  }

  private static final long MOD = 1000000007L;

  static void solve(InputStream is, PrintStream os) {
    Scanner sc = new Scanner(is);

    /* read */
    int n = sc.nextInt();

    String line1 = sc.next();
    String line2 = sc.next();

    List<Boolean> pattern = new ArrayList<>();
    int i = 0;
    while (i < n) {
      if (line1.charAt(i) == line2.charAt(i)) {
        pattern.add(true);
      }
      else {
        pattern.add(false);
        i++;
      }
      i++;
    }

    long ans;
    if (pattern.get(0)) ans = 3;
    else ans = 6;

    for (int j = 1; j < pattern.size(); j++) {
      if (pattern.get(j)) {
        if (pattern.get(j - 1)) ans *= 2;
        else ans *= 1;
      } else {
        if (pattern.get(j - 1)) ans *= 2;
        else {
          ans *= 3;
        }
      }
      ans %= MOD;
    }

    os.println(ans);
  }

  private static <P> List<P> bfs(P start, P end, Function<P, Set<P>> travel,
      Predicate<P> predicate) {
    Set<P> visited = new HashSet<>();
    Queue<List<P>> queue = new LinkedList<>();
    visited.add(start);
    queue.add(Collections.singletonList(start));

    while (!queue.isEmpty()) {
      List<P> path = queue.remove();
      P head = path.get(path.size() - 1);
      Set<P> candidates = travel.apply(head);
      for (P c : candidates) {
        if (!visited.contains(c) && predicate.test(c)) {
          List<P> p = Stream.concat(path.stream(), Stream.of(c)).collect(Collectors.toList());
          queue.add(p);
          visited.add(c);
          if (c.equals(end)) {
            return p;
          }
        }
      }
    }
    return null;
  }

  private static class FermatCombination {

    private long fact[];
    private long mod;

    public FermatCombination(int size, long mod) {
      this.fact = new long[size + 1];
      this.mod = mod;

      this.fact[0] = 1;

      for (int i = 1; i <= size; i++) {
        fact[i] = (fact[i - 1] * i) % mod;
      }
    }

    private long factorial(int n) {
      return fact[n];
    }

    private long inverse(long n) {
      return pow(n, mod - 2) % mod;
    }

    private long pow(long x, long n) {
      long ans = 1;
      while (n > 0) {
        if ((n & 1) == 1) {
          ans = ans * x % mod;
        }
        x = x * x % mod;
        n >>= 1;
      }
      return ans;
    }

    long combination(int n, int k) {
      long ans = 1;
      ans *= factorial(n);
      ans %= mod;
      ans *= inverse(factorial(n - k));
      ans %= mod;
      ans *= inverse(factorial(k));
      ans %= mod;
      return ans;
    }
  }

  private static class Scanner {

    private final InputStream is;
    private final byte[] buffer = new byte[1024];
    private int ptr = 0;
    private int buflen = 0;

    Scanner(InputStream is) {
      this.is = is;
    }

    private boolean hasNextByte() {
      if (ptr < buflen) {
        return true;
      } else {
        ptr = 0;
        try {
          buflen = is.read(buffer);
        } catch (IOException e) {
          e.printStackTrace();
        }
        if (buflen <= 0) {
          return false;
        }
      }
      return true;
    }

    private int readByte() {
      if (hasNextByte()) {
        return buffer[ptr++];
      } else {
        return -1;
      }
    }

    private static boolean isPrintableChar(int c) {
      return 33 <= c && c <= 126;
    }

    public boolean hasNext() {
      while (hasNextByte() && !isPrintableChar(buffer[ptr])) {
        ptr++;
      }
      return hasNextByte();
    }

    public String next() {
      if (!hasNext()) {
        throw new NoSuchElementException();
      }
      StringBuilder sb = new StringBuilder();
      int b = readByte();
      while (isPrintableChar(b)) {
        sb.appendCodePoint(b);
        b = readByte();
      }
      return sb.toString();
    }

    public long nextLong() {
      if (!hasNext()) {
        throw new NoSuchElementException();
      }
      long n = 0;
      boolean minus = false;
      int b = readByte();
      if (b == '-') {
        minus = true;
        b = readByte();
      }
      if (b < '0' || '9' < b) {
        throw new NumberFormatException();
      }
      while (true) {
        if ('0' <= b && b <= '9') {
          n *= 10;
          n += b - '0';
        } else if (b == -1 || !isPrintableChar(b)) {
          return minus ? -n : n;
        } else {
          throw new NumberFormatException();
        }
        b = readByte();
      }
    }

    public int nextInt() {
      long nl = nextLong();
      if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
        throw new NumberFormatException();
      }
      return (int) nl;
    }

    public double nextDouble() {
      return Double.parseDouble(next());
    }
  }
}

import java.util.Scanner;

public class Main {
    private static final long MOD = 1000000007L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            char[][] t = new char[n][2];
            for (int i = 0; i < 2; i++) {
                String s = sc.next();
                for (int j = 0; j < n; j++) {
                    t[j][i] = s.charAt(j);
                }
            }
            System.out.println(solve(n, t));
        }
    }

    private static long solve(int n, char[][] t) {
        long[][][] dp = new long[n + 1][4][4];
        for (int i = 0; i < 3; i++) {
            for (int j = 0; j < 3; j++) {
                if ( t[0][0] == t[0][1] ) {
                    if ( i == j ) {
                        dp[0][i][j] = 1;
                    }
                } else {
                    if ( i != j ) {
                        dp[0][i][j] = 1;
                    }
                }
            }
        }

        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < 3; j++) {
                for (int k = 0; k < 3; k++) {
                    if ( dp[i][j][k] == 0 ) {
                        continue;
                    }

                    for (int nj = 0; nj < 3; nj++) {
                        for (int nk = 0; nk < 3; nk++) {
                            if ( t[i][0] == t[i + 1][0] ) {
                                if ( j == nj && k == nk ) {
                                    dp[i + 1][nj][nk] += dp[i][j][k];
                                    dp[i + 1][nj][nk] %= MOD;
                                }
                            } else {
                                if ( j != nj && k != nk ) {
                                    if ( t[i + 1][0] == t[i + 1][1] && nj == nk ||
                                        t[i + 1][0] != t[i + 1][1] && nj != nk ) {
                                        dp[i + 1][nj][nk] += dp[i][j][k];
                                        dp[i + 1][nj][nk] %= MOD;
                                    }
                                }
                            }
                        }
                    }

                }
            }
        }

        long ans = 0;
        for (int j = 0; j < 3; j++) {
            for (int k = 0; k < 3; k++) {
                ans += dp[n - 1][j][k];
                ans %= MOD;
            }
        }

        return ans;
    }
}

