            S[0] = in.next().toCharArray();
            S[1] = in.next().toCharArray();

            long[] dp = new long[N];
            dp[0] = 3 * (S[0][0] == S[1][0] ? 1 : 2);
            for (int i = 1; i < N; i++) {
                if (S[0][i - 1] == S[0][i]) {
                    dp[i] = dp[i - 1];
                } else if (S[0][i - 1] == S[1][i - 1]) {
                    dp[i] = dp[i - 1] * 2 % MOD;
                } else {
                    if (S[0][i] == S[1][i]) {
                        dp[i] = dp[i - 1];
                    } else {
                        dp[i] = dp[i - 1] * 3 % MOD;
                    }
                }
            }
            out.println(dp[N - 1]);
        }

    }

