    public class UnionFind
    {
        private int[] _par;
        private int[] _rank;

        public UnionFind(int size)
        {
            _par = new int[size + 1];
            _rank = new int[size + 1];
            for (int i = 0; i < _par.Length; i++)
            {
                _par[i] = i;
            }
        }

        public int Root(int x)
        {
            if (_par[x] == x)
                return x;
            else
            {
                _par[x] = Root(_par[x]);
                return _par[x];
            }
        }

        public bool IsSame(int x, int y)
        {
            return Root(x) == Root(y);
        }

        public void Unite(int x, int y)
        {
            x = Root(x);
            y = Root(y);
            if (x == y) return;

            if (_rank[x] < _rank[y])
            {
                _par[x] = y;
            }
            else
            {
                _par[y] = x;
                if (_rank[x] == _rank[y])
                {
                    _rank[x]++;
                }
            }
        }
    }
}

