	public static long BS<T>(IList<T> seq, T value)  where T : IComparable<T> {
		int left = -1;
		int right = seq.Count;
		while (right - left > 1) {
			int mid = left + (right - left) / 2;
			if (0<=seq[mid].CompareTo(value)) right = mid;
			else left = mid;
		}
		return right;
	}
















