static class Program
{
    public static void Main()
    {
        var sw = new StreamWriter(OpenStandardOutput()) { NewLine = "\n" };
#if DEBUG
        sw.AutoFlush = true;
#else
        sw.AutoFlush = false;
#endif
        SetOut(sw);
        Solve(new IO());
        Out.Flush();
    }

    static void Solve(IO io)
    {
        var n = io.I;
        var s1 = io.S;
        var s2 = io.S;

        var f = false;
        var p = new List<bool>();

        for (var i = 0; i < n; i++)
        {
            if (f) { f = false; continue; }
            if (s1[i] == s2[i]) { p.Add(true); f = false; }
            else { p.Add(false); f = true; }
        }

        long ans = p[0] ? 3 : 6;

        for (var i = 1; i < p.Count; i++)
        {
            if ( p[i - 1] && !p[i]) ans *= 2;
            if (!p[i - 1] &&  p[i]) ans *= 1;
            if ( p[i - 1] &&  p[i]) ans *= 2;
            if (!p[i - 1] && !p[i]) ans *= 3;
            ans %= Mod;
        }

        io.Write(ans);
    }
}

