		public class Calc {
			public void Solve() {
				var N = NextInt();
				var S = ReadLine();
				ReadLine();

				var queue = new Queue<bool>();
				for (var i = 0; i < S.Length; i++) {
					if (i == S.Length - 1) {
						queue.Enqueue(true);
						continue;
					}

					if (S[i] != S[i + 1]) {
						queue.Enqueue(true);
					}
					else {
						queue.Enqueue(false);
						i++;
					}
				}

				var ans = queue.First() ? 3L : 6L;
				var before = queue.Dequeue();
				foreach (var item in queue) {
					ans = before ? Mod(ans * 2) : Mod(ans * (item ? 1 : 3));
					before = item;
				}

				Mod(ans).WL();

				return;
			}
		}
	}





