                }
            }
            else
            {
                if (s1[i - 1] == s2[i - 1])
                {
                    ans = ans * 2 % MOD;
                    if(s1[i] != s2[i])
                    {
                        i++;
                    }
                }
                else
                {
                    if(s1[i] != s2[i])
                    {
                        i++;
                        ans = ans * 3 % MOD;
                    }
                }
            }
        }
        Out.Num(ans);
    }
}

