class Myon
{
    public Myon() { }
    public static int Main()
    {
        cin = new Scanner();
        new Myon().calc();
        return 0;
    }

    static Scanner cin;

    // メンバ変数---
    int N;
    string S1;
    string S2;
    const long MOD = 1000000007;
    // -------------

    void calc()
    {
        N = cin.nextInt();
        S1 = cin.next();
        S2 = cin.next();

        long cnt = 0;
        for(int i = 0;i < N-1; i++)
        {
            if(S1[i] != S1[i + 1])
            {
                cnt++;
            }
        }
        for (int i = 0; i < N - 1; i++)
        {
            if (S2[i] != S2[i + 1])
            {
                cnt++;
            }
        }
        long tmp = 0;
        for(int i = 0;i < N; i++)
        {
            if(S1[i] != S2[i])
            {
                tmp++;
            }
        }
        cnt += tmp / 2;
        tmp = (cnt * (Pow(2, (N - 2)) * 3));
        if(N > 1)
        {
            tmp += 3;
        }
        cnt = Pow(3, N) - tmp;
        Write(cnt % MOD);
    }

    void Write(string v)
    {
        Console.WriteLine(v);
    }

    void Write(int v)
    {
        Console.WriteLine(v);
    }

    void Write(double v)
    {
        Console.WriteLine(v);
    }
    void Write(long v)
    {
        Console.WriteLine(v);
    }

    int Pow(int x, int y)
    {
        return (int)Math.Pow(double.Parse(x.ToString()), double.Parse(y.ToString()));
    }

    double Pow(double x, double y)
    {
        return Math.Pow(x, y);
    }

