        static void Solve(Input input)
        {
            var n = input.NextInt();
            var s1 = input.Next();
            var s2 = input.Next();

            // 横方向は全て1マスで良いので便宜上圧縮して考える
            var line1 = new List<char>();
            var prev = ' ';
            foreach (var ch in s1)
            {
                if (prev != ch)
                {
                    line1.Add(ch);
                    prev = ch;
                }
            }

            var line2 = new List<char>();
            prev = ' ';
            foreach (var ch in s2)
            {
                if (prev != ch)
                {
                    line2.Add(ch);
                    prev = ch;
                }
            }

            Console.WriteLine(pat(line1, line2, 0, 0, 0, 3) % MOD);
        }

        static long pat(List<char> l1, List<char> l2, int x, int y, int fromy, int cnum)
        {
            var c = cnum;

            if (x > 0)
            {
                c--;
                if (l1[x] == l2[x] && l1[x - 1] != l2[x - 1])
                {
                    // aab
                    // aab みたいな並び

                    // 2カ所接している
                    c--;
                }
            }
            if (fromy != y && l1[x] != l2[x])
            {
                // 上か下はもう決定済み
                c--;
            }

            int nextx = x, nexty = y;

            // 移動先
            if (y != fromy)
            {
                nextx++;
            }
            else
            {
                if (l1[x] != l2[x])
                {
                    // 横長ドミノなので、縦移動
                    nexty = (y + 1) % 2;
                }
                else
                {
                    // 縦長ドミノなので、横移動
                    nextx++;
                }
            }

            // 横長が連続した場合だけ特殊
            if (x > 0)
            {

                if (l1[x - 1] != l2[x - 1] && l1[x] != l2[x])
                {
                    nextx = x + 1;
                    nexty = 0;
                    c = 3;
                }
            }

            if (nextx < l1.Count())
            {
                // 移動先が縦長ブロックなら、便宜上yを上側に移動する
                if (l1[nextx] == l2[nextx]) nexty = 0;

                return c * pat(l1, l2, nextx, nexty, y, cnum) % MOD;
            }
            else
            {
                // 末尾探索完了
                return c;
            }
        }

