        public int mod = 1000000007;//10^9+7
        public long MulMod(long a, long b) { return (a % mod) * (b % mod) % mod; }
        public long Pow(long a, long b) {
            if (b == 0) return 1;
            if (b % 2 == 1) return (a % mod * Pow(a % mod, b - 1) % mod) % mod;
            else return Pow(a * a % mod, b / 2) % mod;
        }
