    class Problem : IDisposable
    {
        bool IsGCJ;
        int Repeat;
        Scanner sc;
        Printer pr;
        public Problem(bool isGCJ, Scanner scanner, Printer printer)
        {
            sc = scanner;
            pr = printer;
            IsGCJ = isGCJ;
            if (isGCJ) Repeat = sc.nextInt();
            else Read();
        }
        public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
        public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
        public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
        public void Solve()
        {
            if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
            else SolveOne();
        }
        public void Dispose()
        {
            sc.Dispose();
            pr.Dispose();
        }
        public int Size { get { return 1; } }
        public const long Mod = 1000000007;

        // 使用する変数をここに書く
        // string S;
        // int a;
        /// <summary>
        /// 読み込み処理をここに書く
        /// </summary>
        void Read()
        {

        }
        /// <summary>
        /// メイン処理をここに書く
        /// </summary>
        void SolveOne()
        {
            long mod = 1000000007;

            int n = sc.nextInt();
            string s1 = sc.next();
            string s2 = sc.next();

            List<bool> ls = new List<bool>();   //tate = true
            for (int i = 0; i < n; i++)
            {
                if(s1[i]==s2[i])
                {
                    ls.Add(true);
                }
                else
                {
                    ls.Add(false);
                    i++;
                }
            }
            long ans = 3;
            for (int i = 0; i < ls.Count; i++)
            {
                if(i == 0)
                {
                    if(ls[i] == false)
                    {
                        ans *= 2;
                    }
                }
                else
                {
                    if(ls[i-1] == true && ls[i] == true)
                    {
                        ans *= 2;
                    }
                    else if (ls[i - 1] == true && ls[i] == false)
                    {
                        ans *= 2;
                    }
                    else if (ls[i - 1] == false && ls[i] == true)
                    {
                        ans *= 1;
                    }
                    else
                    {
                        ans *= 3;
                    }
                }
                ans %= mod;
            }
            Console.WriteLine(ans);
        }
    }
}
