func solve(stdin io.Reader, stdout io.Writer) {

	r := NewScannerEx(stdin)
	r.Scan(true)
	//n := r.nextInt()
	r.Scan(true)
	s0 := r.nextString()
	r.Scan(true)
	s1 := r.nextString()

	type tateyoko int
	const (
		tate tateyoko = iota
		yoko
		zero
	)
	pret := zero
	t := pret
	ans := 1
	MOD := int(1E9 + 7)
	for s, e, endi := 0, 0, len(s0); s < endi; {

		if s0[e] == s1[e] {
			e++
			t = tate
		} else {
			e += 2
			t = yoko
		}

		w := 0
		if pret == zero {
			switch t {
			case tate:
				w = 3
			case yoko:
				w = 3 * 2
			}

		} else {
			switch t {
			case tate:
				if pret == tate {
					w = 2
				} else {
					w = 1
				}
			case yoko:
				if pret == tate {
					w = 2
				} else {
					w = 3
				}
			}
		}
		ans = ans * w
		s = e
		pret = t
	}

	fmt.Fprintln(stdout, ans%MOD)
}

