                // ac
                // bc
                continue;
            }
            if(s1[i+1] != s2[i+1]) {
                // ab
                // cd
                ans *= 3;
                ans %= p;
                continue;
            }
        } else {
            if(s1[i+1] != s2[i+1]) {
                // ab
                // ac
                ans *= 2;
                ans %= p;
                continue;
            } else {
                // ab
                // ab
                ans *= 2;
                ans %= p;
                continue;
            }
        }
    }
    writeln(ans);
}

