def main():
  MAX = 10**9 + 7

  n = int(input())
  grid = [list(input().strip()) for _ in range(2)]

  i = 0
  lx = []
  while i < n:
    if grid[0][i] == grid[1][i]:
      lx.append('-')
      i += 1
    else:
      lx.append('=')
      i += 2

  cnt = 3 if lx[0] == '-' else 6
  for i in range(1, len(lx)):
    if lx[i-1] == '-' and lx[i] == '-':
      cnt *= 2
    if lx[i-1] == '-' and lx[i] == '=':
      cnt *= 2
    if lx[i-1] == '=' and lx[i] == '-':
      cnt *= 1
    if lx[i-1] == '=' and lx[i] == '=':
      cnt *= 3
    cnt %= MAX
  print(cnt)


if __name__=='__main__':
  main()

