    let mut dp: Vec<i64> = vec![0; n];
    dp[0] = if s1[0] == s2[0] { 3 } else { 6 };

    for i in 1..n {
        let base = dp[i-1];
        if s1[i-1] == s2[i-1] {
            // AB or AB
            // AB    AC
            dp[i] = base * 2 % MOD;
        } else {
            if s1[i-1] == s1[i] {
                // AA
                // BB
                dp[i] = base;
            } else if s1[i] == s2[i] {
                // AC
                // BC
                dp[i] = base;
            } else {
                // AB or AC or AB
                // BA    BA    BC
                dp[i] = base * 3 % MOD;
            }
        }
    }
    println!("{}", dp[n-1]);
}

