fn solve(src: &str) -> String {
    let mut sc = Scanner::from_str(src);

    let n: usize = sc.read();
    let s1: Vec<_> = sc.get().chars().collect();
    let s2: Vec<_> = sc.get().chars().collect();

    let mut a = Vec::new();
    let mut i = 0;
    while i < n {
        if s1[i] == s2[i] {
            a.push(true);
            i += 1;
        } else {
            a.push(false);
            i += 2;
        }
    }

    let mut ptn = Finite(if a[0] { 3 } else { 6 });
    for i in 1..a.len() {
        ptn *= match (a[i-1], a[i]) {
            (true, true) | (true, false) => 2,
            (false, true) => 1,
            (false, false) => 3,
        };
    }

    format!("{}\n", ptn)
}

