fn main() {
    let mut buf = String::new();
    std::io::stdin().read_to_string(&mut buf).unwrap();

    let answer = solve(&buf);

    println!("{}", answer);
}

fn solve(input: &str) -> String {
    let mut iterator = input.split_whitespace();

    let n: usize = iterator.next().unwrap().parse().unwrap();
    let s1: Vec<char> = iterator.next().unwrap().chars().collect();
    let s2: Vec<char> = iterator.next().unwrap().chars().collect();

    let mut is_tate: Vec<bool> = Vec::new();
    let mut i = 0;
    while i < n {
        if s1[i] == s2[i] {
            is_tate.push(true);
        } else {
            is_tate.push(false);
            i += 1;
        }
        i += 1;
    }

    let mut ans: usize = if is_tate[0] {
        3
    } else {
        3 * 2
    };

    const MOD: usize = 1_000_000_007;
    for i in 1..is_tate.len() {
        if is_tate[i - 1] {
            ans *= 2;
        } else {
            if !is_tate[i] {
                ans *= 3;
            }
        }
        ans %= MOD;
    }

    ans.to_string()
}

use std::io::{BufRead, Write};
use std::io;
use std::ops::{Add, Div, Mul, Sub};
use std::iter::Sum;

const MOD: u64 = 1000000007;

#[derive(Clone, Copy)]
struct ModInt {
    pub inner: u64,
}

impl From<u64> for ModInt {
    fn from(i: u64) -> ModInt {
        ModInt { inner: i }
    }
}

impl Add<ModInt> for ModInt {
    type Output = ModInt;
    fn add(self, rhs: ModInt) -> ModInt {
        ModInt {
            inner: (self.inner + rhs.inner) % MOD,
        }
    }
}

impl Sub<ModInt> for ModInt {
    type Output = ModInt;
    fn sub(self, rhs: ModInt) -> ModInt {
        ModInt {
            inner: (self.inner + MOD - rhs.inner) % MOD,
        }
    }
}

impl Mul<ModInt> for ModInt {
    type Output = ModInt;
    fn mul(self, rhs: ModInt) -> ModInt {
        ModInt {
            inner: (self.inner * rhs.inner) % MOD,
        }
    }
}

impl Sum for ModInt {
    fn sum<I: Iterator<Item = ModInt>>(iter: I) -> ModInt {
        iter.fold(ModInt::from(0), Add::add)
    }
}

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut s = String::new();
    input.read_line(&mut s).unwrap();
    let _: usize = s.trim().parse().unwrap();
    s.clear();
    input.read_line(&mut s).unwrap();
    let s1 = s.trim().as_bytes().to_owned();
    s.clear();
    input.read_line(&mut s).unwrap();
    let _ = s.trim().as_bytes().to_owned();
    #[derive(Clone, Copy)]
    enum BlockType {
        Horizontal,
        Vertical,
    }
    let mut bt: Vec<BlockType> = Vec::new();
    let mut i = 0;
    while i != s1.len() {
        if i == s1.len() - 1 || s1[i] != s1[i + 1] {
            bt.push(BlockType::Vertical);
            i += 1;
        } else {
            bt.push(BlockType::Horizontal);
            i += 2;
        }
    }
    let mut total = ModInt {
        inner: match bt[0] {
            BlockType::Horizontal => 6,
            BlockType::Vertical => 3,
        },
    };
    for x in bt.windows(2) {
        total = total * ModInt {
            inner: match (x[0], x[1]) {
                (BlockType::Horizontal, BlockType::Horizontal) => 3,
                (BlockType::Horizontal, BlockType::Vertical) => 1,
                (BlockType::Vertical, BlockType::Horizontal) => 2,
                (BlockType::Vertical, BlockType::Vertical) => 2,
            },
        }
    }
    writeln!(output, "{}", total.inner).unwrap();
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    solve(stdin.lock(), stdout.lock());
}

