enum DKind {
    X,
    Y,
}

fn solve() {
    let n = get!(usize);
    let s = get!([chars; 2]);

    let (mut ans, mut col, mut kind) = if s[0][0] == s[1][0] {
        (3u64, 1, DKind::X)
    } else {
        (6u64, 2, DKind::Y)
    };
    while col < n {
        let v = if s[0][col] == s[1][col] {
            match kind {
                DKind::X => {
                    kind = DKind::X;
                    col += 1;
                    2
                }
                DKind::Y => {
                    kind = DKind::X;
                    col += 1;
                    1
                }
            }
        } else {
            match kind {
                DKind::X => {
                    kind = DKind::Y;
                    col += 2;
                    2
                }
                DKind::Y => {
                    kind = DKind::Y;
                    col += 2;
                    3
                }
            }
        };
        ans *= v;
        ans %= 1_000_000_007;
    }
    echo!(ans);
}

