fn main(){
    input!{
        n:usize,
        s:[chars;2],
    }
    let MOD:usize = 1000000007;
    let mut dp = vec![vec![vec![0;3];3];100];
    for i in 0..3{
        for j in 0..3{
            if s[0][0] == s[1][0] && i == j{
                dp[1][i][j] = 1;
            }
            if s[0][0] != s[1][0] && i != j{
                dp[1][i][j] = 1;
            }
        }
    }
    for i in 1..n{
        if s[0][i] != s[1][i]{
            for j in 0..3{
                for k in 0..3{
                    if j == k{continue;}

                    if i != 0 && s[0][i] != s[0][i-1]{
                        for l in 0..3{
                            for m in 0..3{
                                if j == l || k == m{continue;}
                                dp[i+1][j][k] = (dp[i+1][j][k] + dp[i][l][m])%MOD;
                            }
                        }
                    }

                    else{
                        dp[i+1][j][k] = dp[i][j][k];
                    }
                }
            }
        }
        else{
            for j in 0..3{
                for l in 0..3{
                    for m in 0..3{
                        if j == l || j == m{continue;}
                        dp[i+1][j][j] = (dp[i+1][j][j] + dp[i][l][m])%MOD;
                    }
                }
            }

        }

    }
    let mut res = 0;
    for i in 0..3{
        for j in 0..3{
            res = (res + dp[n][i][j])%MOD;
        }
    }
    println!("{:?}", res);

}

