fn run() {
    input! {
        n: usize,
        s: [chars; 2],
    }
    let mut ans = if s[0][0] == s[1][0] {
        ModInt(3)
    } else {
        ModInt(6)
    };
    for i in 1..n {
        if s[0][i] == s[0][i - 1] {
            continue;
        }
        ans *= match (s[0][i - 1] == s[1][i - 1], s[0][i] == s[1][i]) {
            (true, true) => ModInt(2),
            (true, false) => ModInt(2),
            (false, true) => ModInt(1),
            (false, false) => ModInt(3),
        };
    }
    println!("{}", ans);
}

